fn pending_page_draw(
    identity: u32,
    pipeline_index: u32,
    mode: TerrainMaterialPassMode,
    page_addressed: bool,
    distance_squared: f32,
) -> PendingMeshDraw {
    let handle = |kind, index| Handle::new(kind, index, 1).unwrap();
    let pipeline = handle(HandleKind::GraphicsPipeline, pipeline_index);
    let layout = handle(HandleKind::PipelineLayout, 1);
    let set = handle(HandleKind::ResourceSet, 1);
    PendingMeshDraw {
        draw: TerrainMeshDraw {
            shadow: Some(TerrainShadowDraw {
                pipeline,
                pipeline_layout: layout,
                resource_set: set,
                resource_set_dynamic_offsets: vec![0, 0].into(),
                shader_resource_set: None,
            }),
            pipeline,
            offscreen_pipeline: None,
            pipeline_layout: layout,
            resource_set: set,
            resource_set_dynamic_offsets: vec![0, 0].into(),
            shader_resource_set: None,
            index_buffer: handle(HandleKind::Buffer, 1),
            index_offset: 0,
            index_type: IndexType::U16,
            index_count: identity,
            instance_count: 1,
            indexed_indirect: None,
            stratum: WORLD_STRATUM_TERRAIN,
            material_mode: mode,
            shadow_participation: TerrainShadowParticipation::Required,
        },
        page_command: page_addressed.then_some(PageIndexedDrawCommand {
            index_count: identity,
            instance_count: 1,
            first_index: identity,
            vertex_offset: 0,
            first_instance: identity,
        }),
        front_to_back_distance_squared: distance_squared,
    }
}

#[test]
fn private_dh_draws_reuse_pass_local_pipeline_and_lightmap_bindings() {
    let handle = |kind, index| Handle::new(kind, index, 1).unwrap();
    let mut first = pending_page_draw(6, 1, TerrainMaterialPassMode::Opaque, false, 0.0).draw;
    first.offscreen_pipeline = Some(handle(HandleKind::GraphicsPipeline, 10));
    first.shader_resource_set = Some(TerrainShaderResourceSet {
        set_index: 1,
        set: handle(HandleKind::ResourceSet, 20),
    });
    let mut second = first.clone();
    second.resource_set = handle(HandleKind::ResourceSet, 2);
    let mut third = second.clone();
    third.offscreen_pipeline = Some(handle(HandleKind::GraphicsPipeline, 11));
    let mut ops = Vec::new();

    append_private_dh_draws(&[first, second, third], &mut ops).unwrap();

    assert_eq!(
        2,
        ops.iter()
            .filter(|op| matches!(op, CommandOp::BindGraphicsPipeline(_)))
            .count()
    );
    assert_eq!(
        3,
        ops.iter()
            .filter(|op| matches!(op, CommandOp::BindResourceSet { set_index: 0, .. }))
            .count()
    );
    assert_eq!(
        2,
        ops.iter()
            .filter(|op| matches!(op, CommandOp::BindResourceSet { set_index: 1, .. }))
            .count()
    );
    assert_eq!(
        3,
        ops.iter()
            .filter(|op| matches!(op, CommandOp::DrawIndexed { .. }))
            .count()
    );
}

#[test]
fn page_indirect_order_groups_compatible_draws_without_crossing_boundaries() {
    let mut draws = vec![
        pending_page_draw(30, 3, TerrainMaterialPassMode::Opaque, true, 30.0),
        pending_page_draw(10, 1, TerrainMaterialPassMode::Opaque, true, 10.0),
        pending_page_draw(99, 9, TerrainMaterialPassMode::Opaque, false, 0.0),
        pending_page_draw(40, 4, TerrainMaterialPassMode::Cutout, true, 40.0),
        pending_page_draw(20, 2, TerrainMaterialPassMode::Cutout, true, 20.0),
    ];

    order_compatible_page_indirect_draws(&mut draws);

    assert_eq!(
        vec![10, 30, 99, 20, 40],
        draws
            .iter()
            .map(|pending| pending.draw.index_count)
            .collect::<Vec<_>>()
    );
    assert!(draws[2].page_command.is_none());
    assert_eq!(TerrainMaterialPassMode::Opaque, draws[1].draw.material_mode);
    assert_eq!(TerrainMaterialPassMode::Cutout, draws[3].draw.material_mode);
}

#[test]
fn page_indirect_order_sorts_compatible_draws_front_to_back() {
    let mut draws = vec![
        pending_page_draw(30, 1, TerrainMaterialPassMode::Cutout, true, 900.0),
        pending_page_draw(10, 1, TerrainMaterialPassMode::Cutout, true, 100.0),
        pending_page_draw(20, 1, TerrainMaterialPassMode::Cutout, true, 400.0),
    ];

    order_compatible_page_indirect_draws(&mut draws);

    assert_eq!(
        vec![10, 20, 30],
        draws
            .iter()
            .map(|pending| pending.draw.index_count)
            .collect::<Vec<_>>()
    );
    assert!(draws
        .windows(2)
        .all(|pair| page_indirect_draw_order(&pair[0], &pair[1]) == std::cmp::Ordering::Equal));
}

#[test]
fn translucent_page_draws_keep_camera_order_across_pipeline_changes() {
    let mut draws = vec![
        pending_page_draw(30, 3, TerrainMaterialPassMode::Translucent, true, 900.0),
        pending_page_draw(10, 1, TerrainMaterialPassMode::Translucent, true, 100.0),
        pending_page_draw(20, 2, TerrainMaterialPassMode::Translucent, true, 400.0),
    ];

    order_compatible_page_indirect_draws(&mut draws);

    assert_eq!(
        vec![30, 10, 20],
        draws
            .iter()
            .map(|pending| pending.draw.index_count)
            .collect::<Vec<_>>()
    );
}

