#[test]
fn selected_source_preview_decodes_half_float_color_before_png_encoding() {
    let bytes = [
        0x00, 0x3c, // 1.0
        0x00, 0x38, // 0.5
        0x00, 0x00, // 0.0
        0x00, 0x3c, // 1.0 alpha
    ];
    assert_eq!(
        selected_source_preview_rgba(TextureFormat::Rgba16Float, &bytes),
        vec![255, 128, 0, 255]
    );
    let evidence = attachment_evidence_json_for_format(
        1,
        1,
        "final_output",
        TextureFormat::Rgba16Float,
        &bytes,
    );
    assert!(evidence.contains("Rgba16Float"));
    assert!(evidence.contains("\"nonblack_rgb\":1"));
}
