fn selected_source_asset_refresh_uses_current_streaming_frame() {
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend.enable_candidate_lowered_source_execution_for_test();
    let mut frame = shader_mesh_scene_frame(128, 128, 0);
    enter_shader_candidate_overworld(&mut frame);
    frame.voxel_volume = private_voxel_volume_frame([0.25, 0.5, 0.75]);
    for instance in &mut frame.mesh_instances {
        instance.stratum = WORLD_STRATUM_TERRAIN;
    }

    frontend.ensure_shader_runtime(&mut gal, 1).unwrap();
    assert!(frontend.shader_runtime.is_some());
    assert!(
        frontend.should_refresh_candidate_source_assets_for_frame(&frame),
        "current-frame source assembly must not wait for a second matching visible list"
    );
}

#[test]
fn distant_horizons_source_targets_stage_and_retire_as_one_generation() {
    let source = complete_bundled_pack_source_for_test();
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend.enable_candidate_source_preparation_for_test();
    frontend
        .apply_shader_pack_source_update(ShaderPackSourceUpdate {
            pack_name: source.name().to_string(),
            generation: source.generation(),
            files: source.files(),
        })
        .unwrap();
    frontend
        .ensure_shader_runtime(&mut gal, source.generation())
        .unwrap();
    frontend.observe_shader_pack_source_candidate_for_scope(TerrainProgramScope::Overworld);

    let extent = Extent3d {
        width: 96,
        height: 64,
        depth: 1,
    };
    let staged = frontend
        .stage_distant_horizons_source_targets(&mut gal, 41, 17, extent)
        .unwrap()
        .expect("the bundled source retains a complete DH color/depth target contract");
    let colors = staged.color_targets;
    let depth = staged.depth_targets;
    assert_eq!(17, colors.identity.world_generation);
    assert_eq!(source.generation(), colors.identity.shader_pack_generation);
    assert_eq!(extent, colors.identity.extent);
    assert_eq!(17, depth.identity.world_generation);
    assert_eq!(source.generation(), depth.identity.shader_pack_generation);
    assert_eq!(extent, depth.identity.extent);
    assert_eq!(
        Some(HandleKind::Texture),
        depth.distant_depth_texture.kind()
    );
    assert_eq!(
        Some(HandleKind::TextureView),
        depth.distant_depth_view.kind()
    );
    let program = frontend
        .shader_runtime
        .as_ref()
        .expect("shader runtime remains installed while source targets are staged")
        .prepared_lowered_distant_horizons_source_program()
        .unwrap()
        .expect("bundled source retains the lowered DH program");
    let staged_color_resources = frontend
        .shader_runtime
        .as_mut()
        .unwrap()
        .stage_distant_horizons_source_color_resources(&mut gal, &program, &colors)
        .expect("DH source color samplers must stage with the shared named target generation");
    assert_eq!(
        source.generation(),
        staged_color_resources
            .availability()
            .shader_pack_generation()
    );
    let mismatch = frontend
        .candidate_source_resources_for_distant_horizons_program(
            &mut gal, 18, 41, &program, &colors, &depth,
        )
        .unwrap_err();
    assert!(
        mismatch
            .to_string()
            .contains("does not match requested world18"),
        "unexpected DH source target mismatch: {mismatch}"
    );

    frontend.discard_distant_horizons_source_targets(&mut gal);
    assert_eq!(None, frontend.lod_source_targets.active_identity());

    let shared_colors = frontend
        .shader_runtime
        .as_mut()
        .unwrap()
        .stage_source_color_targets(&mut gal, 17, extent)
        .unwrap()
        .expect("the normal terrain owner must stage one shared named color generation");
    let restaged = frontend
        .stage_distant_horizons_source_targets_for_colors(
            &mut gal,
            42,
            17,
            extent,
            shared_colors.clone(),
        )
        .unwrap()
        .expect("DH depth targets must stage against the normal terrain color generation");
    assert_eq!(shared_colors.identity, restaged.color_targets.identity);
    assert!(frontend
        .confirm_distant_horizons_source_targets(&mut gal, staged.submission)
        .unwrap_err()
        .to_string()
        .contains("does not match"));
    frontend
        .shader_runtime
        .as_mut()
        .unwrap()
        .stage_distant_horizons_source_color_resources(
            &mut gal,
            &program,
            &restaged.color_targets,
        )
        .expect("DH source sampler promotion must be tied to its confirmed target pair");
    frontend
        .confirm_distant_horizons_source_targets(&mut gal, restaged.submission)
        .unwrap();
    assert_eq!(
        Some(restaged.depth_targets.identity),
        frontend.lod_source_targets.active_identity()
    );

    frontend.destroy_resources(&mut gal);
    assert_eq!(None, frontend.lod_source_targets.active_identity());
}

#[test]
fn textured_material_source_targets_are_distinct_load_only_named_passes() {
    let source = complete_bundled_pack_source_for_test();
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend.enable_candidate_source_preparation_for_test();
    frontend
        .apply_shader_pack_source_update(ShaderPackSourceUpdate {
            pack_name: source.name().to_string(),
            generation: source.generation(),
            files: source.files(),
        })
        .unwrap();
    frontend
        .ensure_shader_runtime(&mut gal, source.generation())
        .unwrap();
    frontend.observe_shader_pack_source_candidate_for_scope(TerrainProgramScope::Overworld);

    let program = frontend
        .shader_runtime
        .as_ref()
        .unwrap()
        .prepared_lowered_textured_material_source_program()
        .unwrap()
        .expect("bundled selected source must retain gbuffers_textured");
    let extent = Extent3d {
        width: 96,
        height: 64,
        depth: 1,
    };
    let color_targets = frontend
        .shader_runtime
        .as_mut()
        .unwrap()
        .stage_source_color_targets(&mut gal, 17, extent)
        .unwrap()
        .expect("selected source must stage named color targets");
    let depth_texture = gal
        .create_texture(TextureDesc {
            label: "textured-material-source.depth".to_string(),
            dimension: TextureDimension::D2,
            format: TextureFormat::Depth32Float,
            extent,
            mip_levels: 1,
            array_layers: 1,
            usages: vec![TextureUsage::DepthStencilAttachment, TextureUsage::Sampled],
        })
        .unwrap();
    let depth_view = gal
        .create_texture_view(TextureViewDesc {
            label: "textured-material-source.depth.view".to_string(),
            texture: depth_texture,
            format: TextureFormat::Depth32Float,
            base_mip: 0,
            mip_count: 1,
            base_layer: 0,
            layer_count: 1,
        })
        .unwrap();
    let targets = frontend
        .stage_textured_material_source_color_pass_targets(
            &mut gal,
            17,
            41,
            extent,
            &program,
            &color_targets,
            depth_texture,
            depth_view,
            ShaderPackColorClearValues {
                fog_color: ClearColor {
                    r: 0.1,
                    g: 0.2,
                    b: 0.3,
                    a: 1.0,
                },
            },
        )
        .unwrap()
        .clone();
    assert_eq!(TerrainSourceColorPassPhase::TexturedMaterial, targets.phase);
    assert_eq!(
        vec![
            TerrainPassOutput::LitTerrainColor,
            TerrainPassOutput::MaterialAuxiliary,
            TerrainPassOutput::TranslucencyAuxiliary,
        ],
        targets
            .color_attachments
            .iter()
            .map(|attachment| attachment.output)
            .collect::<Vec<_>>(),
    );
    assert_eq!(
        vec![0, 6, 3],
        targets
            .color_attachments
            .iter()
            .map(|attachment| attachment.source_slot)
            .collect::<Vec<_>>(),
    );
    assert!(!targets.target.is_null());
    assert!(!targets.pass.is_null());
}

