#[test]
fn source_material_staging_requires_explicit_classification_and_preserves_raw_light() {
    let mut source_frame = frame(Vec::new());
    // The selected source declares the complete Complementary scalar
    // contract. Populate the copied semantic environment here rather
    // than weakening the material writer test with an internal fixture.
    source_frame.shader_environment = WorldShaderEnvironmentFrame {
        enabled: true,
        world_generation: 1,
        world_time: 12_345,
        frame_counter: 42,
        frame_time_seconds: 0.016,
        frame_time_counter: 12.5,
        world_day: 17,
        moon_phase: 3,
        time_of_day: 0.75,
        rain_strength: 0.25,
        thunder_strength: 0.5,
        sky_darken: 0.125,
        eye_submersion: 1,
        screen_brightness: 0.75,
        far_plane: 192.0,
        configured_shadow_distance_chunks: 32,
        distant_horizons_render_distance: 256,
        relative_eye_position: [0.25, -0.5, 0.75],
        sky_color: [0.2, 0.4, 0.6],
        darkness_light_factor: 0.125,
        blindness: 0.25,
        darkness_factor: 0.5,
        eye_brightness: [80, 240],
        night_vision: 0.875,
        fog_color: [0.3, 0.5, 0.7],
        fog_parameter_color: [0.1, 0.2, 0.4, 0.8],
        fog_environmental_start: 12.0,
        fog_environmental_end: 96.0,
        fog_render_distance_start: 24.0,
        fog_render_distance_end: 128.0,
        fog_sky_end: 128.0,
        fog_clouds_end: 96.0,
        biome_precipitation: 2,
        biome_resource_location: "minecraft:snowy_plains".to_string(),
        main_hand_item_model_resource_location: "minecraft:lava_bucket".to_string(),
        off_hand_item_model_resource_location: "minecraft:totem_of_undying".to_string(),
        main_hand_item_light_emission: 13,
        off_hand_item_light_emission: 7,
        vanilla_lightmap: None,
    };
    source_frame.voxel_volume = WorldVoxelVolumeFrame {
        enabled: true,
        world_generation: 1,
        resource_generation: 1,
        camera_world_position: [12.5, 64.0, -3.25],
    };
    let mut quad = material_quad(WORLD_MATERIAL_MODE_CUTOUT, WORLD_DEPTH_POLICY_TEST_WRITE);
    quad.source_program = WORLD_MATERIAL_SOURCE_TEXTURED;
    quad.source_color_argb = 0x7f12_3456;
    quad.packed_light = 0x00f0_00b0;
    quad.vertex_color_argb = [0x7f12_3456; 4];
    quad.vertex_packed_light = [0x00f0_00b0; 4];
    source_frame.material_quads.push(quad);

    let staged = stage_source_material_primitives(&source_frame).unwrap();
    assert_eq!(1, staged.len());
    assert_eq!(0x7f12_3456, staged[0].vertices[0].source_color_argb);
    assert_eq!(0x00f0_00b0, staged[0].vertices[0].packed_light);
    assert_eq!([0.0, 0.0, 1.0], staged[0].vertices[0].geometric_normal);

    let error = WorldPrimitiveFrontend::default()
        .validate_selected_source_frame_coverage(&source_frame)
        .unwrap_err();
    assert!(error.to_string().contains("no Rust shader runtime"));

    source_frame.material_quads[0].source_program = WORLD_MATERIAL_SOURCE_UNSPECIFIED;
    let error = stage_source_material_primitives(&source_frame).unwrap_err();
    assert!(error.to_string().contains("not classified"));
}

#[test]
fn prepared_source_material_frame_uses_atlas_stream_and_quad_expansion_contract() {
    let source = complete_bundled_pack_source_for_test();
    let mut runtime = ShaderPackRuntimeExecutor::terrain_material_multipass_v1(1).unwrap();
    runtime.observe_source_candidate_for_scope(&source, TerrainProgramScope::Overworld);
    let program = runtime
        .prepared_lowered_textured_material_source_program()
        .unwrap()
        .expect("bundled selected source must retain gbuffers_textured");
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend
        .apply_shader_pack_source_update(ShaderPackSourceUpdate {
            pack_name: source.name().to_string(),
            generation: source.generation(),
            files: source.files(),
        })
        .unwrap();
    frontend
        .apply_shader_pack_asset_update(copied_source_png_assets(&source))
        .unwrap();
    frontend
        .apply_world_mesh_asset_update(
            &mut gal,
            1,
            Vec::new(),
            vec![WorldMeshTextureAssetPayload {
                texture_id: WORLD_MESH_TEXTURE_TERRAIN_BLOCK_ATLAS,
                png_bytes: material_scene_png(0),
                mip_png_bytes: Vec::new(),
                frame_width: 0,
                frame_height: 0,
                frame_count: 1,
                frame_ticks: 1,
                animation_flags: 0,
                frame_row_size: 0,
                interpolation_policy: 0,
                animation_frames: Vec::new(),
                coordinate_origin: 0,
                sampling: None,
                requested_mip_levels: 0,
            }],
        )
        .unwrap();
    let mut source_frame = frame(Vec::new());
    source_frame.shader_environment = complete_source_material_test_environment();
    source_frame.voxel_volume = WorldVoxelVolumeFrame {
        enabled: true,
        world_generation: 1,
        resource_generation: 1,
        camera_world_position: [12.5, 64.0, -3.25],
    };
    let mut quad = material_quad(WORLD_MATERIAL_MODE_CUTOUT, WORLD_DEPTH_POLICY_TEST_WRITE);
    quad.source_program = WORLD_MATERIAL_SOURCE_TEXTURED;
    quad.source_uv_space = WORLD_MATERIAL_SOURCE_UV_MINECRAFT_BLOCK_ATLAS;
    quad.packed_light = 0x00e0_00a0;
    source_frame.material_quads.push(quad);
    let transforms = frontend
        .source_texture_transforms_for_owned_resources()
        .unwrap();
    let uniforms = frontend
        .source_uniform_frame_for_owned_resources(&source_frame)
        .unwrap();
    let prepared = frontend
        .prepare_textured_material_source_frame(&program, &source_frame, &transforms, &uniforms)
        .unwrap();
    assert_eq!(source_frame.frame_id, prepared.frame_id);
    assert_eq!(1, prepared.primitives.len());
    assert_eq!(
        4 * program.execution_interface.vertex_stride as usize,
        prepared.vertex_stream.len(),
    );
    assert_eq!(
        program.execution_interface.legacy_transform_bytes as usize,
        prepared.legacy_texture_transforms.len(),
    );
    assert_eq!(
        program.execution_interface.scalar_uniform_bytes as usize,
        prepared.scalar_uniforms.len(),
    );

    source_frame.material_quads[0].source_uv_space = WORLD_MATERIAL_SOURCE_UV_LOCAL_TEXTURE;
    let transforms = frontend
        .source_texture_transforms_for_owned_resources()
        .unwrap();
    let uniforms = frontend
        .source_uniform_frame_for_owned_resources(&source_frame)
        .unwrap();
    let local_prepared = frontend
        .prepare_textured_material_source_frame(&program, &source_frame, &transforms, &uniforms)
        .unwrap();
    assert_eq!(
        prepared.vertex_stream, local_prepared.vertex_stream,
        "source stream preserves local UVs; resource selection is per batch"
    );
}

#[test]
fn source_material_batches_keep_texture_and_uv_resource_contracts_separate() {
    let mut source_frame = frame(Vec::new());
    let mut atlas = material_quad(WORLD_MATERIAL_MODE_CUTOUT, WORLD_DEPTH_POLICY_TEST_WRITE);
    atlas.source_program = WORLD_MATERIAL_SOURCE_TEXTURED;
    atlas.source_uv_space = WORLD_MATERIAL_SOURCE_UV_MINECRAFT_BLOCK_ATLAS;
    atlas.texture_id = WORLD_MESH_TEXTURE_TERRAIN_BLOCK_ATLAS;

    let mut local_a = atlas.clone();
    local_a.source_uv_space = WORLD_MATERIAL_SOURCE_UV_LOCAL_TEXTURE;
    local_a.texture_id = WORLD_MATERIAL_TEXTURE_BLOCK_MARKER_BARRIER;

    let mut local_b = local_a.clone();
    local_b.texture_id = WORLD_MATERIAL_TEXTURE_BLOCK_MARKER_LIGHT_00;

    source_frame.material_quads = vec![atlas, local_a.clone(), local_a, local_b];
    let batches = source_textured_material_batches(&source_frame).unwrap();

    assert_eq!(3, batches.len());
    assert_eq!(
        WORLD_MESH_TEXTURE_TERRAIN_BLOCK_ATLAS,
        batches[0].texture_id
    );
    assert_eq!(
        WORLD_MATERIAL_SOURCE_UV_MINECRAFT_BLOCK_ATLAS,
        batches[0].source_uv_space
    );
    assert_eq!(
        WORLD_MATERIAL_TEXTURE_BLOCK_MARKER_BARRIER,
        batches[1].texture_id
    );
    assert_eq!(
        WORLD_MATERIAL_SOURCE_UV_LOCAL_TEXTURE,
        batches[1].source_uv_space
    );
    assert_eq!(2, batches[1].count);
    assert_eq!(
        WORLD_MATERIAL_TEXTURE_BLOCK_MARKER_LIGHT_00,
        batches[2].texture_id
    );
}

