#[test]
fn dedicated_post_effect_route_rejects_resource_pack_overrides() {
    let mut frontend = WorldPrimitiveFrontend::default();
    let bundled = complete_bundled_pack_source_for_test();
    frontend
        .apply_shader_pack_source_update(ShaderPackSourceUpdate {
            pack_name: bundled.name().to_string(),
            generation: bundled.generation(),
            files: bundled.files(),
        })
        .unwrap();
    frontend
        .apply_shader_pack_asset_update(ShaderPackAssetUpdate {
            pack_name: bundled.name().to_string(),
            generation: bundled.generation(),
            files: vec![ShaderPackAssetFile::new(
                "post_effect/transparency.json",
                include_bytes!(
                    "../../../resources/assets/minecraft/post_effect/transparency.json"
                )
                .to_vec(),
            )],
        })
        .unwrap();
    assert!(frontend
        .dedicated_post_effect_is_bundled("transparency")
        .unwrap());
    frontend
        .validate_post_effect_request(b"minecraft:transparency", test_conventions())
        .expect(
            "bundled Fabulous transparency is admitted through its dedicated Rust executor",
        );

    let override_bytes = String::from_utf8(
        include_bytes!("../../../resources/assets/minecraft/post_effect/transparency.json")
            .to_vec(),
    )
    .unwrap()
    .replace("minecraft:translucent", "minecraft:main")
    .into_bytes();
    frontend
        .apply_shader_pack_source_update(ShaderPackSourceUpdate {
            pack_name: bundled.name().to_string(),
            generation: bundled.generation() + 1,
            files: bundled.files(),
        })
        .unwrap();
    frontend
        .apply_shader_pack_asset_update(ShaderPackAssetUpdate {
            pack_name: bundled.name().to_string(),
            generation: bundled.generation() + 1,
            files: vec![ShaderPackAssetFile::new(
                "post_effect/transparency.json",
                override_bytes,
            )],
        })
        .unwrap();
    assert!(!frontend
        .dedicated_post_effect_is_bundled("transparency")
        .unwrap());
    assert!(
        frontend
            .validate_post_effect_request(b"minecraft:transparency", test_conventions())
            .is_err(),
        "a resource-pack transparency override must not be routed through bundled Rust shaders"
    );
}

#[test]
fn held_light_uniforms_follow_hand_changes_and_policy_reload() {
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend
        .apply_world_mesh_asset_update(
            &mut gal,
            1,
            Vec::new(),
            vec![WorldMeshTextureAssetPayload {
                texture_id: WORLD_MESH_TEXTURE_TERRAIN_BLOCK_ATLAS,
                png_bytes: material_scene_png(0),
                mip_png_bytes: Vec::new(),
                frame_width: 0,
                frame_height: 0,
                frame_count: 1,
                frame_ticks: 1,
                animation_flags: 0,
                frame_row_size: 0,
                interpolation_policy: 0,
                animation_frames: Vec::new(),
                coordinate_origin: 0,
                sampling: None,
                requested_mip_levels: 0,
            }],
        )
        .unwrap();
    let mut source = frame(Vec::new());
    source.shader_environment = WorldShaderEnvironmentFrame {
        enabled: true,
        world_generation: 5,
        far_plane: 128.0,
        ..WorldShaderEnvironmentFrame::default()
    };
    // These are the per-stack Light block values covered by the Java producer
    // test. They arrive independently; only the active native policy combines them.
    for (generation, properties, legacy) in [
        (7, "", true),
        (8, "oldHandLight=false\n", false),
        (9, "oldHandLight=true\n", true),
    ] {
        frontend
            .apply_shader_pack_source_update(ShaderPackSourceUpdate {
                pack_name: "held-light-state-regression".to_string(),
                generation,
                files: vec![ShaderSourceFile::new("shaders.properties", properties)],
            })
            .unwrap();
        for (main, off) in [(3, 12), (12, 3), (1, 3), (0, 0)] {
            source.frame_id += 1;
            source.shader_environment.main_hand_item_light_emission = main;
            source.shader_environment.off_hand_item_light_emission = off;
            let uniforms = frontend
                .source_uniform_frame_for_owned_resources(&source)
                .unwrap();
            assert_eq!(Some(if legacy { main.max(off) } else { main }), uniforms.held_block_light_main);
            assert_eq!(Some(off), uniforms.held_block_light_off_hand);
            // Multiple consumers of the same frame observe identical values.
            let repeated = frontend
                .source_uniform_frame_for_owned_resources(&source)
                .unwrap();
            assert_eq!(uniforms.held_block_light_main, repeated.held_block_light_main);
            assert_eq!(uniforms.held_block_light_off_hand, repeated.held_block_light_off_hand);
        }
    }
}

#[test]
fn owned_source_uniform_preparation_derives_rain_factor_once_per_frame() {
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend
        .apply_world_mesh_asset_update(
            &mut gal,
            1,
            Vec::new(),
            vec![WorldMeshTextureAssetPayload {
                texture_id: WORLD_MESH_TEXTURE_TERRAIN_BLOCK_ATLAS,
                png_bytes: material_scene_png(0),
                mip_png_bytes: Vec::new(),
                frame_width: 0,
                frame_height: 0,
                frame_count: 1,
                frame_ticks: 1,
                animation_flags: 0,
                frame_row_size: 0,
                interpolation_policy: 0,
                animation_frames: Vec::new(),
                coordinate_origin: 0,
                sampling: None,
                requested_mip_levels: 0,
            }],
        )
        .unwrap();
    frontend
        .apply_shader_pack_source_update(ShaderPackSourceUpdate {
            pack_name: "held-item-identities".to_string(),
            generation: 7,
            files: vec![ShaderSourceFile::new(
                "item.properties",
                "item.45032=minecraft:lava_bucket\nitem.45108=minecraft:totem_of_undying\n",
            )],
        })
        .unwrap();
    let mut source = frame(Vec::new());
    source.shader_environment = WorldShaderEnvironmentFrame {
        enabled: true,
        world_generation: 5,
        frame_time_seconds: 1.5,
        rain_strength: 0.0,
        biome_precipitation: 0,
        biome_resource_location: "minecraft:nether_wastes".to_string(),
        main_hand_item_model_resource_location: "minecraft:lava_bucket".to_string(),
        off_hand_item_model_resource_location: "minecraft:totem_of_undying".to_string(),
        main_hand_item_light_emission: 3,
        off_hand_item_light_emission: 12,
        far_plane: 128.0,
        configured_shadow_distance_chunks: 32,
        distant_horizons_render_distance: 256,
        ..WorldShaderEnvironmentFrame::default()
    };
    source.frame_id = 10;
    assert_eq!(
        Some(0.0),
        frontend
            .source_uniform_frame_for_owned_resources(&source)
            .unwrap()
            .rain_factor
    );
    assert_eq!(
        Some(1.0),
        frontend
            .source_uniform_frame_for_owned_resources(&source)
            .unwrap()
            .biome_dry
    );
    let uniforms = frontend
        .source_uniform_frame_for_owned_resources(&source)
        .unwrap();
    assert_eq!(Some(45_032), uniforms.held_item_id_main);
    assert_eq!(Some(45_108), uniforms.held_item_id_off_hand);
    assert_eq!(Some(12), uniforms.held_block_light_main);
    assert_eq!(Some(12), uniforms.held_block_light_off_hand);
    assert_eq!(
        Some(1.0),
        frontend
            .source_uniform_frame_for_owned_resources(&source)
            .unwrap()
            .biome_nether_wastes
    );

    source.frame_id = 11;
    source.shader_environment.rain_strength = 1.0;
    source.shader_environment.biome_precipitation = 2;
    source.shader_environment.biome_resource_location = "minecraft:warped_forest".to_string();
    let smoothed = frontend
        .source_uniform_frame_for_owned_resources(&source)
        .unwrap()
        .rain_factor
        .unwrap();
    assert!((smoothed - 0.5).abs() < 0.000_001);
    let climate = frontend
        .source_uniform_frame_for_owned_resources(&source)
        .unwrap();
    assert!((climate.biome_dry.unwrap() - 0.353_553_38).abs() < 0.000_001);
    assert!((climate.biome_snowy.unwrap() - 0.405_396_46).abs() < 0.000_001);
    assert!((climate.biome_nether_wastes.unwrap() - 0.5).abs() < 0.000_001);
    assert!((climate.biome_warped_forest.unwrap() - 0.5).abs() < 0.000_001);
    assert_eq!(
        Some(smoothed),
        frontend
            .source_uniform_frame_for_owned_resources(&source)
            .unwrap()
            .rain_factor
    );

    source.shader_environment.world_generation = 6;
    source.frame_id = 12;
    source.shader_environment.rain_strength = 0.25;
    source.shader_environment.biome_precipitation = 1;
    assert_eq!(
        Some(0.25),
        frontend
            .source_uniform_frame_for_owned_resources(&source)
            .unwrap()
            .rain_factor
    );
    let reset_climate = frontend
        .source_uniform_frame_for_owned_resources(&source)
        .unwrap();
    assert_eq!(Some(0.0), reset_climate.biome_dry);
    assert_eq!(Some(0.0), reset_climate.biome_snowy);
}

