#[test]
fn world_mesh_groups_compatible_instances_into_one_instanced_draw() {
    let mut gal = gal();
    let target = frame_target(&mut gal, 1, 128, 128);
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend
        .apply_world_mesh_asset_update(
            &mut gal,
            1,
            vec![mesh_asset(181, 1, IndexType::U16)],
            Vec::new(),
        )
        .unwrap();
    let mut frame = frame(Vec::new());
    for index in 0..32 {
        let mut instance = mesh_instance(181, 1);
        instance.transform[12] = index as f32;
        frame.mesh_instances.push(instance);
    }

    let (ops, stats) = frontend
        .append_frame_ops(&mut gal, 1, target, frame)
        .unwrap();

    assert_eq!(32, stats.mesh_instance_count);
    assert_eq!(1, stats.mesh_batch_count);
    assert_eq!(1, stats.mesh_draw_count);
    assert_eq!(
        Some(HandleKind::ResourceSet),
        frontend
            .mesh_resources
            .values()
            .next()
            .unwrap()
            .resource_set
            .kind()
    );
    assert_eq!(1, frontend.mesh_instance_stream_slots.len());
    assert_eq!(
        1,
        ops.iter()
            .filter(|op| matches!(
                op,
                CommandOp::DrawIndexed {
                    indices: 6,
                    instances: 32
                }
            ))
            .count()
    );
    assert!(ops.iter().any(|op| matches!(
        op,
        CommandOp::HostWriteBuffer { data, .. }
            if data.len() == WORLD_MESH_BATCH_HEADER_BYTES + 32 * WORLD_MESH_INSTANCE_BYTES
    )));
}

#[test]
fn world_mesh_vertex_packing_preserves_exact_packed_light_coordinates() {
    let dark = WorldMeshVertex {
        position: [0.0, 0.0, 0.0],
        uv: [0.0, 0.0],
        shader_atlas_uv: [0.25, 0.5],
        shader_block_id: 10232,
        shader_material_type: -1,
        terrain_material_bits: 0b101,
        mid_block_packed: 0,
        color_argb: 0xffff_ffff,
        normal_packed: 0,
        light: 0,
    };
    let lit = WorldMeshVertex {
        light: (15 << 4) | (15 << 20),
        ..dark
    };

    let dark_bytes = packed_mesh_vertices(&[dark]);
    let lit_bytes = packed_mesh_vertices(&[lit]);
    // `extra_data.xy` begins at byte 48. Frozen Sodium feeds zero packed
    // light through a_LightAndData.xy / 256, i.e. the (0, 0) lightmap
    // coordinate; zero must never become an implicit full-bright marker.
    let dark_light = [
        f32::from_le_bytes(dark_bytes[48..52].try_into().unwrap()),
        f32::from_le_bytes(dark_bytes[52..56].try_into().unwrap()),
    ];
    let lit_light = [
        f32::from_le_bytes(lit_bytes[48..52].try_into().unwrap()),
        f32::from_le_bytes(lit_bytes[52..56].try_into().unwrap()),
    ];

    assert_eq!([0.0, 0.0], dark_light);
    assert_eq!([1.0, 1.0], lit_light);

    let dim = WorldMeshVertex {
        light: 1 << 4,
        ..dark
    };
    let dim_bytes = packed_mesh_vertices(&[dim]);
    let dim_light = [
        f32::from_le_bytes(dim_bytes[48..52].try_into().unwrap()),
        f32::from_le_bytes(dim_bytes[52..56].try_into().unwrap()),
    ];
    assert_eq!([1.0 / 15.0, 0.0], dim_light);
    let material_bits = u32::from_le_bytes(dark_bytes[60..64].try_into().unwrap());
    assert_eq!(5.0, f32::from_le_bytes(material_bits.to_le_bytes()));
}

#[test]
fn world_mesh_vertex_packing_preserves_blend_alpha_independent_of_light() {
    let vertex = WorldMeshVertex {
        position: [0.0, 0.0, 0.0],
        uv: [0.0, 0.0],
        shader_atlas_uv: [0.0, 0.0],
        shader_block_id: 0,
        shader_material_type: 0,
        terrain_material_bits: 0,
        mid_block_packed: 0,
        color_argb: 0x40ff_ffff,
        normal_packed: 0,
        light: (3 << 4) | (12 << 20),
    };

    let bytes = packed_mesh_vertices(&[vertex]);
    // normal_light.w is byte 44 in the explicit 80-byte vertex ABI. It
    // feeds v_color.a, which controls terrain translucent blending.
    assert_eq!(
        64.0 / 255.0,
        f32::from_le_bytes(bytes[44..48].try_into().unwrap())
    );
}

#[test]
fn direct_static_terrain_compaction_is_lossless_for_consumed_lanes() {
    let vertex = WorldMeshVertex {
        position: [1.25, -2.5, 3.75],
        uv: [0.125, 0.875],
        shader_atlas_uv: [0.3125, 0.6875],
        shader_block_id: 10232,
        shader_material_type: 1,
        terrain_material_bits: 0x105,
        mid_block_packed: 0,
        color_argb: 0x8040_80c0,
        normal_packed: 0x0012_3456,
        light: 0x00b0_0070,
    };
    let rich = packed_mesh_vertices(&[vertex]);
    let compact = compact_direct_terrain_vertices(&rich).unwrap();
    assert_eq!(WORLD_MESH_DIRECT_TERRAIN_VERTEX_BYTES, compact.len());
    assert_eq!(
        [1.25, -2.5, 3.75],
        [
            read_f32(&compact, 0),
            read_f32(&compact, 1),
            read_f32(&compact, 2)
        ]
    );
    assert_eq!(0x105, u32::from_ne_bytes(compact[12..16].try_into().unwrap()));
    assert_eq!(
        [0.3125, 0.6875],
        [read_f32(&compact, 4), read_f32(&compact, 5)]
    );
    assert_eq!(
        0x80c0_8040,
        u32::from_ne_bytes(compact[24..28].try_into().unwrap())
    );
    assert_eq!(
        0x0000_b070,
        u32::from_ne_bytes(compact[28..32].try_into().unwrap())
    );
}

#[test]
fn compact_vertex_abi_is_admitted_only_for_direct_atlas_terrain() {
    let mut instance = mesh_instance(77, 1);
    instance.stratum = WORLD_STRATUM_TERRAIN;
    let mut section = mesh_asset(77, 1, IndexType::U16).sections.remove(0);
    section.texture_id = WORLD_MESH_TEXTURE_TERRAIN_BLOCK_ATLAS;
    let compact = mesh_key_for_section(
        &instance,
        &section,
        0,
        section.cull_policy,
        1,
        4,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    );
    assert_eq!(
        MeshVertexAbi::DirectTerrain32,
        mesh_vertex_abi_for_builtin(compact)
    );
    assert_eq!(
        STATIC_COMPACT_DIRECT_TERRAIN_OPAQUE_PROGRAM_ID,
        mesh_pipeline_key(compact)
            .unwrap()
            .shader_program_identity
            .as_str()
    );
    let animated = MeshResourceKey {
        texture_animated: true,
        ..compact
    };
    assert_eq!(
        COMPACT_DIRECT_TERRAIN_OPAQUE_PROGRAM_ID,
        mesh_pipeline_key(animated)
            .unwrap()
            .shader_program_identity
            .as_str()
    );
    assert_eq!(
        MeshVertexAbi::Rich80,
        mesh_vertex_abi_for_builtin(MeshResourceKey {
            g_buffer: true,
            ..compact
        })
    );
    assert_eq!(
        MeshVertexAbi::DirectTerrain32,
        mesh_vertex_abi_for_builtin(MeshResourceKey {
            material_mode: WORLD_MATERIAL_MODE_TRANSLUCENT,
            ..compact
        })
    );
    assert_eq!(
        MeshVertexAbi::Rich80,
        mesh_vertex_abi_for_builtin(MeshResourceKey {
            stratum: WORLD_STRATUM_ENTITY_MESH,
            ..compact
        })
    );
}

#[test]
fn mesh_light_coordinates_preserve_fractional_levels_and_sampler_endpoints() {
    for block in 0u32..=255 {
        for sky in 0u32..=255 {
            let packed = block | (sky << 16);
            assert_eq!(
                [block as f32, sky as f32],
                source_lightmap_coordinates(packed)
            );
            let channels = packed_light_channels(packed);
            for (encoded, byte) in channels.into_iter().zip([block, sky]) {
                assert!((encoded * (15.0 / 16.0) - byte as f32 / 256.0).abs() < 0.000001);
            }
        }
    }
}

