#[test]
fn world_lod_column_contract_is_quad_aligned_generation_bound_and_layer_explicit() {
    let vertex = WorldLodVertex {
        local_position: [4, 8, 12],
        packed_light_and_micro_offset: 0x3579,
        color_rgba: [40, 80, 120, 255],
        material_id: 3,
        normal_index: 5,
    };
    let asset = WorldLodColumnAsset {
        column_key: 0x4c4f445f434f4c55,
        column_generation: 7,
        vertex_layout_version: WORLD_LOD_VERTEX_LAYOUT_V1,
        origin: [-512, 64, 1024],
        segments: vec![WorldLodSegment {
            layer: WORLD_LOD_LAYER_OPAQUE,
            vertices: vec![vertex; 4],
        }],
    };
    validate_world_lod_column_asset(&asset).unwrap();
    validate_world_lod_column_instance(
        &WorldLodColumnInstanceRequest {
            column_key: asset.column_key,
            column_generation: asset.column_generation,
            layer: WORLD_LOD_LAYER_OPAQUE,
            segment_index: 0,
            order: 0,
        },
        &asset,
    )
    .unwrap();

    let mut incomplete = asset.clone();
    incomplete.segments[0].vertices.pop();
    assert!(validate_world_lod_column_asset(&incomplete)
        .unwrap_err()
        .to_string()
        .contains("quad-aligned"));

    let wrong_generation = WorldLodColumnInstanceRequest {
        column_key: asset.column_key,
        column_generation: asset.column_generation + 1,
        layer: WORLD_LOD_LAYER_OPAQUE,
        segment_index: 0,
        order: 0,
    };
    assert!(
        validate_world_lod_column_instance(&wrong_generation, &asset)
            .unwrap_err()
            .to_string()
            .contains("does not match")
    );

    let mut unknown_material = asset.clone();
    unknown_material.segments[0].vertices[0].material_id = WORLD_LOD_MAX_MATERIAL_ID + 1;
    assert!(validate_world_lod_column_asset(&unknown_material)
        .unwrap_err()
        .to_string()
        .contains("material category"));

    let mut unknown_normal = asset;
    unknown_normal.segments[0].vertices[0].normal_index = WORLD_LOD_MAX_NORMAL_INDEX + 1;
    assert!(validate_world_lod_column_asset(&unknown_normal)
        .unwrap_err()
        .to_string()
        .contains("face normal"));
}

