#[test]
fn world_mesh_geometry_arena_reuses_released_ranges_without_new_buffers() {
    let mut gal = gal();
    let mut arena = MeshGeometryArena::default();

    let (vertex_buffer, vertex_offset) = arena
        .allocate_vertex(&mut gal, "released-vertex", 1_024)
        .unwrap();
    let (index_buffer, index_offset) = arena
        .allocate_index(&mut gal, "released-index", 512)
        .unwrap();
    arena.release_vertex(vertex_buffer, vertex_offset, 1_024);
    arena.release_index(index_buffer, index_offset, 512);

    let (reused_vertex_buffer, reused_vertex_offset) = arena
        .allocate_vertex(&mut gal, "reused-vertex", 1_024)
        .unwrap();
    let (reused_index_buffer, reused_index_offset) =
        arena.allocate_index(&mut gal, "reused-index", 512).unwrap();

    assert_eq!(vertex_buffer, reused_vertex_buffer);
    assert_eq!(vertex_offset, reused_vertex_offset);
    assert_eq!(index_buffer, reused_index_buffer);
    assert_eq!(index_offset, reused_index_offset);
    assert_eq!(1, arena.vertex_pages.len());
    assert_eq!(1, arena.index_pages.len());
}

#[test]
fn vulkan_mesh_vertex_pages_stage_distinct_ranges_into_device_local_residency() {
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend.defer_world_uploads = true;
    let mut ranges = Vec::new();
    for _ in 0..2 {
        let (vertex_buffer, vertex_offset) = frontend
            .mesh_geometry_arena
            .allocate_vertex(&mut gal, "staged-vertex", 32)
            .unwrap();
        let (index_buffer, index_offset) = frontend
            .mesh_geometry_arena
            .allocate_index(&mut gal, "staged-index", 6)
            .unwrap();
        let resources = MeshGeometryResources {
            vertex_buffer,
            vertex_offset,
            vertex_range: 32,
            vertex_stride: 32,
            index_buffer,
            index_offset,
            index_range: 6,
        };
        frontend
            .upload_mesh_geometry_resources(&mut gal, &resources, vec![7; 32], vec![0; 6])
            .unwrap();
        ranges.push(resources);
    }
    let page = &frontend.mesh_geometry_arena.vertex_pages[0];
    let staging = page.staging_buffer.expect("Vulkan vertex page has staging");
    assert!(page.upload_initialized);
    assert_eq!(ranges[0].vertex_buffer, ranges[1].vertex_buffer);
    assert_ne!(ranges[0].vertex_offset, ranges[1].vertex_offset);
    let copies = frontend
        .pending_world_upload_ops
        .iter()
        .filter_map(|op| match op {
            CommandOp::CopyBufferRegion {
                src,
                src_offset,
                dst,
                dst_offset,
                size,
            } => Some((*src, *src_offset, *dst, *dst_offset, *size)),
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(2, copies.len());
    for (copy, resource) in copies.iter().zip(&ranges) {
        assert_eq!(copy.0, staging);
        assert_eq!(copy.1, resource.vertex_offset);
        assert_eq!(copy.2, resource.vertex_buffer);
        assert_eq!(copy.3, resource.vertex_offset);
        assert_eq!(copy.4, resource.vertex_range);
    }
    frontend.flush_pending_world_uploads(&mut gal).unwrap();
}

#[test]
fn world_mesh_geometry_arena_trims_fully_released_pages() {
    let mut gal = gal();
    let mut arena = MeshGeometryArena::default();

    let (vertex_buffer, vertex_offset) = arena
        .allocate_vertex(&mut gal, "trim-vertex", 1_024)
        .unwrap();
    let (index_buffer, index_offset) =
        arena.allocate_index(&mut gal, "trim-index", 512).unwrap();
    arena.release_vertex(vertex_buffer, vertex_offset, 1_024);
    arena.release_index(index_buffer, index_offset, 512);

    arena.trim_empty_pages(&mut gal);

    assert!(arena.vertex_pages.is_empty());
    assert!(arena.index_pages.is_empty());
    assert_eq!(3, gal.metrics().resource_destroys);
}

#[test]
fn world_mesh_accepts_moving_mesh_stratum() {
    let mut gal = gal();
    let target = frame_target(&mut gal, 1, 128, 128);
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend
        .apply_world_mesh_asset_update(
            &mut gal,
            1,
            vec![mesh_asset(184, 1, IndexType::U16)],
            Vec::new(),
        )
        .unwrap();
    let mut frame = frame(Vec::new());
    let mut instance = mesh_instance(184, 1);
    instance.stratum = WORLD_STRATUM_MOVING_MESH;
    frame.mesh_instances.push(instance);

    let (_, stats) = frontend
        .append_frame_ops(&mut gal, 1, target, frame)
        .unwrap();

    assert_eq!(1, stats.mesh_instance_count);
    assert_eq!(1, stats.mesh_batch_count);
    assert_eq!(1, stats.mesh_draw_count);
}

#[test]
fn world_mesh_accepts_generic_entity_mesh_stratum_but_source_admission_requires_its_writer() {
    let mut gal = gal();
    let target = frame_target(&mut gal, 1, 128, 128);
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend
        .apply_world_mesh_asset_update(
            &mut gal,
            1,
            vec![mesh_asset(186, 1, IndexType::U16)],
            Vec::new(),
        )
        .unwrap();
    let mut normal_frame = frame(Vec::new());
    let mut entity_instance = mesh_instance(186, 1);
    entity_instance.stratum = WORLD_STRATUM_ENTITY_MESH;
    normal_frame.mesh_instances.push(entity_instance.clone());
    let (_, stats) = frontend
        .append_frame_ops(&mut gal, 1, target, normal_frame)
        .unwrap();
    assert_eq!(1, stats.mesh_instance_count);
    assert_eq!(1, stats.mesh_draw_count);

    let mut source_frame = frame(Vec::new());
    source_frame.mesh_instances.push(entity_instance);
    let error = frontend
        .validate_selected_source_frame_coverage(&source_frame)
        .expect_err(
            "selected source admission must not silently claim generic entity ownership",
        );
    let message = error.to_string();
    assert!(
        message.contains("entity work but no Rust shader runtime")
            || message.contains("entity meshes but no lowered gbuffers_entities writer"),
        "generic entity mesh must remain unadmitted until its source writer is discovered: {message}"
    );
}

