fn shader_mesh_vertex(
    position: [f32; 3],
    uv: [f32; 2],
    color_argb: u32,
    light: u32,
    normal: [f32; 3],
) -> WorldMeshVertex {
    WorldMeshVertex {
        position,
        uv,
        shader_atlas_uv: uv,
        shader_block_id: 12,
        shader_material_type: 1,
        terrain_material_bits: 0,
        mid_block_packed: 0,
        color_argb,
        normal_packed: pack_normal_i8(normal),
        light,
    }
}

