#[allow(clippy::too_many_arguments)]
fn material_scene_quad(
    x0: f32,
    y0: f32,
    x1: f32,
    y1: f32,
    z: f32,
    material_mode: u32,
    cull_policy: u32,
    winding: u32,
    color_argb: u32,
    uv: [f32; 4],
    width: u32,
    height: u32,
) -> WorldMaterialQuadRequest {
    WorldMaterialQuadRequest {
        stratum: WORLD_STRATUM_OPAQUE_TEXTURED_GEOMETRY,
        material_id: if material_mode == WORLD_MATERIAL_MODE_CUTOUT {
            WORLD_MATERIAL_ID_DEFAULT_CUTOUT
        } else {
            WORLD_MATERIAL_ID_DEFAULT_OPAQUE
        },
        texture_id: WORLD_MATERIAL_TEXTURE_DEFAULT,
        material_mode,
        depth_policy: WORLD_DEPTH_POLICY_TEST_WRITE,
        cull_policy,
        topology: WORLD_TOPOLOGY_TRIANGLES,
        winding,
        color_argb,
        vertices: [[x0, y0, z], [x1, y0, z], [x1, y1, z], [x0, y1, z]],
        uvs: [
            [uv[0], uv[1]],
            [uv[2], uv[1]],
            [uv[2], uv[3]],
            [uv[0], uv[3]],
        ],
        viewport_width: width,
        viewport_height: height,
        source_program: WORLD_MATERIAL_SOURCE_UNSPECIFIED,
        source_uv_space: WORLD_MATERIAL_SOURCE_UV_LOCAL_TEXTURE,
        source_color_argb: color_argb,
        packed_light: 0,
        vertex_color_argb: [color_argb; 4],
        vertex_packed_light: [0; 4],
        block_entity_id: -1,
    }
}

