fn crop_from_ndc(
    name: &'static str,
    width: u32,
    height: u32,
    x0: f32,
    y0: f32,
    x1: f32,
    y1: f32,
) -> Crop {
    let left = (((x0 * 0.5 + 0.5) * width as f32).floor() as i32).clamp(0, width as i32 - 1);
    let right = (((x1 * 0.5 + 0.5) * width as f32).ceil() as i32).clamp(1, width as i32);
    let top =
        (((1.0 - (y1 * 0.5 + 0.5)) * height as f32).floor() as i32).clamp(0, height as i32 - 1);
    let bottom =
        (((1.0 - (y0 * 0.5 + 0.5)) * height as f32).ceil() as i32).clamp(1, height as i32);
    Crop {
        name,
        x: left as u32,
        y: top as u32,
        width: (right - left).max(1) as u32,
        height: (bottom - top).max(1) as u32,
    }
}

fn non_clear_pixels(pixels: &[u8], width: u32, crop: Crop) -> usize {
    non_clear_pixels_with_clear(pixels, width, crop, [8, 10, 18])
}

fn non_clear_pixels_with_clear(
    pixels: &[u8],
    width: u32,
    crop: Crop,
    clear_rgb: [u8; 3],
) -> usize {
    let mut count = 0;
    for y in crop.y..crop.y + crop.height {
        for x in crop.x..crop.x + crop.width {
            let index = ((y * width + x) * 4) as usize;
            let px = &pixels[index..index + 4];
            if px[0].abs_diff(clear_rgb[0]) > 4
                || px[1].abs_diff(clear_rgb[1]) > 4
                || px[2].abs_diff(clear_rgb[2]) > 4
            {
                count += 1;
            }
        }
    }
    count
}

fn write_material_report(
    backend: RuntimeBackend,
    width: u32,
    height: u32,
    semantic_hash: u32,
    initial: &RuntimeRenderResult,
    rollback: &RuntimeRenderResult,
    reloaded: &RuntimeRenderResult,
    resized: &RuntimeRenderResult,
) -> GalResult<()> {
    let root = repo_root().join("logs/rust-vulkanic/material-conformance");
    let dir = root.join(backend.label());
    std::fs::create_dir_all(&dir).map_err(|error| {
        GalError::backend(format!(
            "failed to create material conformance dir: {error}"
        ))
    })?;
    write_png(
        &dir.join("full-initial.png"),
        width,
        height,
        &initial.pixels,
    )?;
    for crop in material_feature_crops(width, height) {
        write_crop(
            &dir.join(format!("crop-{}.png", crop.name)),
            width,
            &initial.pixels,
            crop,
        )?;
    }
    write_png(
        &dir.join("full-rollback.png"),
        width,
        height,
        &rollback.pixels,
    )?;
    write_png(
        &dir.join("full-reloaded.png"),
        width,
        height,
        &reloaded.pixels,
    )?;
    write_png(
        &dir.join("full-resized.png"),
        width + 32,
        height + 16,
        &resized.pixels,
    )?;
    let crop_counts = material_feature_crops(width, height)
        .into_iter()
        .zip(initial.feature_non_clear.iter())
        .map(|(crop, count)| format!("\"{}\":{}", crop.name, count))
        .collect::<Vec<_>>()
        .join(",");
    let json = format!(
        "{{\n  \"artifact_class\":\"world_material_runtime_conformance\",\n  \"backend\":\"{}\",\n  \"semantic_request_hash\":\"{:08x}\",\n  \"width\":{},\n  \"height\":{},\n  \"initial_hash\":\"{:08x}\",\n  \"rollback_hash\":\"{:08x}\",\n  \"reloaded_hash\":\"{:08x}\",\n  \"resized_hash\":\"{:08x}\",\n  \"feature_non_clear\":{{{}}},\n  \"material_quad_count\":{},\n  \"material_batch_count\":{},\n  \"material_draw_count\":{},\n  \"material_cache_misses\":{},\n  \"rollback_material_cache_hits\":{},\n  \"rollback_preserved_last_valid_texture\":{},\n  \"screenshots\":[\"full-initial.png\",\"full-rollback.png\",\"full-reloaded.png\",\"full-resized.png\"]\n}}\n",
        backend.name(),
        semantic_hash,
        width,
        height,
        initial.hash,
        rollback.hash,
        reloaded.hash,
        resized.hash,
        crop_counts,
        initial.stats.material_quad_count,
        initial.stats.material_batch_count,
        initial.stats.material_draw_count,
        initial.stats.material_cache_misses,
        rollback.stats.material_cache_hits,
        initial.hash == rollback.hash
    );
    std::fs::write(dir.join("latest.json"), json).map_err(|error| {
        GalError::backend(format!(
            "failed to write material conformance report: {error}"
        ))
    })
}

fn write_shader_mesh_report(
    backend: RuntimeBackend,
    width: u32,
    height: u32,
    semantic_hash: u32,
    frames: &[RuntimeRenderResult],
    rollback: &RuntimeRenderResult,
    reloaded: &RuntimeRenderResult,
) -> GalResult<()> {
    let root = std::env::var_os("MATTMC_SHADER_GBUFFER_ARTIFACT_DIR")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| repo_root().join("logs/rust-vulkanic/shader-pack-conformance"));
    let dir = root.join(backend.label());
    std::fs::create_dir_all(&dir).map_err(|error| {
        GalError::backend(format!(
            "failed to create shader-pack conformance dir: {error}"
        ))
    })?;
    for (index, frame) in frames.iter().enumerate() {
        write_png(
            &dir.join(format!("full-airborne-frame-{index}.png")),
            width,
            height,
            &frame.pixels,
        )?;
        for crop in shader_mesh_feature_crops(width, height) {
            write_crop(
                &dir.join(format!("crop-frame-{index}-{}.png", crop.name)),
                width,
                &frame.pixels,
                crop,
            )?;
        }
    }
    if let Some(first) = frames.first() {
        write_shader_mesh_attachment_artifacts(&dir, width, height, first)?;
    }
    write_png(
        &dir.join("full-rollback.png"),
        width,
        height,
        &rollback.pixels,
    )?;
    write_png(
        &dir.join("full-reloaded.png"),
        width,
        height,
        &reloaded.pixels,
    )?;
    let frame_hashes = frames
        .iter()
        .map(|frame| format!("\"{:08x}\"", frame.hash))
        .collect::<Vec<_>>()
        .join(",");
    let crop_names = shader_mesh_feature_crops(width, height)
        .iter()
        .map(|crop| format!("\"{}\"", crop.name))
        .collect::<Vec<_>>()
        .join(",");
    let first_counts = frames
        .first()
        .map(|frame| {
            shader_mesh_feature_crops(width, height)
                .into_iter()
                .zip(frame.feature_non_clear.iter())
                .map(|(crop, count)| format!("\"{}\":{}", crop.name, count))
                .collect::<Vec<_>>()
                .join(",")
        })
        .unwrap_or_default();
    let attachment_hashes = frames
        .first()
        .map(|frame| {
            frame
                .attachment_hashes
                .iter()
                .map(|(name, hash)| format!("\"{}\":\"{:08x}\"", name, hash))
                .collect::<Vec<_>>()
                .join(",")
        })
        .unwrap_or_default();
    let attachment_evidence = frames
        .first()
        .map(|frame| shader_mesh_attachment_evidence_json(width, height, frame))
        .unwrap_or_else(|| "{}".to_string());
    let perturbation_evidence = frames
        .first()
        .map(|frame| shader_mesh_perturbation_evidence_json(width, height, frame))
        .unwrap_or_else(|| "{}".to_string());
    let chain_evidence = frames
        .first()
        .map(shader_mesh_composite_chain_evidence_json)
        .unwrap_or_else(|| "{}".to_string());
    let mesh_draws = frames
        .iter()
        .map(|frame| frame.stats.mesh_draw_count)
        .sum::<u64>();
    let json = format!(
        "{{\n  \"artifact_class\":\"rust_owned_shader_pack_mesh_conformance\",\n  \"backend\":\"{}\",\n  \"shader_pack_generation\":1,\n  \"shader_config_schema\":1,\n  \"pass_graph_generation\":3,\n  \"semantic_request_hash\":\"{:08x}\",\n  \"pass_graph\":\"vulkanic:builtin/terrain_material_multipass_v1\",\n  \"passes\":[\"vulkanic:pass/shadow_depth\",\"vulkanic:pass/terrain_opaque\",\"vulkanic:pass/terrain_cutout\",\"vulkanic:pass/deferred_lighting\",\"vulkanic:pass/terrain_translucent\",\"vulkanic:pass/composite_0\",\"vulkanic:pass/composite_1\",\"vulkanic:pass/final_output\"],\n  \"executed_pass_order\":[\"shadow_depth\",\"terrain_opaque\",\"terrain_cutout\",\"deferred_lighting\",\"terrain_translucent\",\"composite_0_color_grade\",\"composite_1_depth_fog\",\"final_output\"],\n  \"g_buffer_attachments\":[\"shadow_depth\",\"albedo\",\"normal\",\"material_light\",\"world_position\",\"depth\",\"deferred_lit\",\"composite_0\",\"composite_1\"],\n  \"attachment_formats\":{{\"shadow_depth\":\"Depth32Float\",\"albedo\":\"Rgba16Float\",\"normal\":\"Rgba16Float\",\"material_light\":\"Rgba16Float\",\"world_position\":\"Rgba16Float\",\"depth\":\"Depth32Float\",\"deferred_lit\":\"Rgba16Float\",\"composite_0\":\"Rgba16Float\",\"composite_1\":\"Rgba16Float\",\"final_composite\":\"Rgba8Unorm\"}},\n  \"attachment_extents\":{{\"width\":{},\"height\":{}}},\n  \"attachment_hashes\":{{{}}},\n  \"attachment_semantic_evidence\":{},\n  \"shadow_dependency_evidence\":{},\n  \"composite_dependency_perturbations\":{},\n  \"composite_chain_evidence\":{},\n  \"final_presentation_owner\":\"rust-backend-owned-target\",\n  \"rust_owned_color_attachment\":true,\n  \"rust_owned_depth_attachment\":true,\n  \"rust_owned_shadow_attachment\":true,\n  \"java_iris_participation\":false,\n  \"width\":{},\n  \"height\":{},\n  \"airborne_frame_hashes\":[{}],\n  \"rollback_hash\":\"{:08x}\",\n  \"reloaded_hash\":\"{:08x}\",\n  \"rollback_preserved_last_valid_generation\":{},\n  \"crop_names\":[{}],\n  \"frame0_feature_non_clear\":{{{}}},\n  \"mesh_instance_count\":{},\n  \"mesh_batch_count\":{},\n  \"mesh_draw_count\":{},\n  \"mesh_cache_hits\":{},\n  \"mesh_cache_misses\":{},\n  \"mesh_asset_payload_bytes\":{},\n  \"screenshots\":[\"full-airborne-frame-0.png\",\"full-airborne-frame-1.png\",\"full-airborne-frame-2.png\",\"full-airborne-frame-3.png\",\"full-airborne-frame-4.png\",\"full-rollback.png\",\"full-reloaded.png\"],\n  \"attachment_dumps\":[\"attachment-shadow_depth.png\",\"attachment-shadow_depth.raw\",\"attachment-albedo.png\",\"attachment-normal.png\",\"attachment-material_light.png\",\"attachment-world_position.png\",\"attachment-depth.png\",\"attachment-depth.raw\",\"attachment-deferred_lit.png\",\"attachment-composite_0.png\",\"attachment-composite_1.png\",\"attachment-final_composite.png\"]\n}}\n",
        backend.name(),
        semantic_hash,
        width,
        height,
        attachment_hashes,
        attachment_evidence,
        shader_mesh_shadow_evidence_json(backend, width, height, frames),
        perturbation_evidence,
        chain_evidence,
        width,
        height,
        frame_hashes,
        rollback.hash,
        reloaded.hash,
        rollback.hash == frames[0].hash,
        crop_names,
        first_counts,
        frames[0].stats.mesh_instance_count,
        frames[0].stats.mesh_batch_count,
        mesh_draws,
        frames
            .iter()
            .map(|frame| frame.stats.mesh_cache_hits)
            .sum::<u64>(),
        frames
            .iter()
            .map(|frame| frame.stats.mesh_cache_misses)
            .sum::<u64>(),
        frames[0].stats.mesh_asset_payload_bytes
    );
    std::fs::write(dir.join("latest.json"), json).map_err(|error| {
        GalError::backend(format!(
            "failed to write shader-pack mesh conformance report: {error}"
        ))
    })
}

fn write_shader_mesh_attachment_artifacts(
    dir: &std::path::Path,
    width: u32,
    height: u32,
    frame: &RuntimeRenderResult,
) -> GalResult<()> {
    for name in [
        "albedo",
        "normal",
        "material_light",
        "world_position",
        "deferred_lit",
        "composite_0",
        "composite_1",
        "final_composite",
    ] {
        let Some(bytes) = frame.attachments.get(name) else {
            continue;
        };
        write_png(
            &dir.join(format!("attachment-{name}.png")),
            width,
            height,
            bytes,
        )?;
    }
    if let Some(depth) = frame.attachments.get("depth") {
        std::fs::write(dir.join("attachment-depth.raw"), depth).map_err(|error| {
            GalError::backend(format!("failed to write depth raw attachment: {error}"))
        })?;
        let depth_rgba = depth_attachment_to_grayscale_rgba(depth);
        write_png(
            &dir.join("attachment-depth.png"),
            width,
            height,
            &depth_rgba,
        )?;
    }
    if let Some(depth) = frame.attachments.get("shadow_depth") {
        std::fs::write(dir.join("attachment-shadow_depth.raw"), depth).map_err(|error| {
            GalError::backend(format!(
                "failed to write shadow depth raw attachment: {error}"
            ))
        })?;
        let depth_rgba = depth_attachment_to_grayscale_rgba(depth);
        write_png(
            &dir.join("attachment-shadow_depth.png"),
            width,
            height,
            &depth_rgba,
        )?;
    }
    Ok(())
}

fn shader_mesh_attachment_evidence_json(
    width: u32,
    height: u32,
    frame: &RuntimeRenderResult,
) -> String {
    let mut entries = Vec::new();
    for name in [
        "shadow_depth",
        "albedo",
        "normal",
        "material_light",
        "world_position",
        "deferred_lit",
        "composite_0",
        "composite_1",
        "depth",
        "final_composite",
    ] {
        let Some(bytes) = frame.attachments.get(name) else {
            entries.push(format!("\"{name}\":{{\"present\":false}}"));
            continue;
        };
        let evidence = if name == "depth" || name == "shadow_depth" {
            depth_attachment_evidence_json(bytes)
        } else {
            color_attachment_evidence_json(width, height, name, bytes)
        };
        entries.push(format!("\"{name}\":{evidence}"));
    }
    format!("{{{}}}", entries.join(","))
}

fn color_attachment_evidence_json(width: u32, height: u32, name: &str, bytes: &[u8]) -> String {
    let mut alpha_pixels = 0usize;
    let mut non_default = 0usize;
    let mut distinct = BTreeMap::new();
    let default = match name {
        "normal" => [128, 128, 255, 255],
        "material_light" => [0, 255, 255, 0],
        "albedo" | "deferred_lit" | "composite_0" | "composite_1" | "final_composite" => {
            [16, 40, 218, 255]
        }
        _ => [0, 0, 0, 0],
    };
    for px in bytes.chunks_exact(4) {
        if px[3] > 0 {
            alpha_pixels += 1;
        }
        if px[0].abs_diff(default[0]) > 3
            || px[1].abs_diff(default[1]) > 3
            || px[2].abs_diff(default[2]) > 3
            || px[3].abs_diff(default[3]) > 3
        {
            non_default += 1;
        }
        if distinct.len() < 64 {
            distinct.insert([px[0], px[1], px[2], px[3]], ());
        }
    }
    let crop_counts = shader_mesh_feature_crops(width, height)
        .into_iter()
        .map(|crop| {
            format!(
                "\"{}\":{}",
                crop.name,
                non_clear_pixels_with_clear(
                    bytes,
                    width,
                    crop,
                    [default[0], default[1], default[2]]
                )
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    format!(
        "{{\"present\":true,\"hash\":\"{:08x}\",\"alpha_pixels\":{},\"non_default_pixels\":{},\"distinct_rgba_sample_count\":{},\"feature_non_default\":{{{}}}}}",
        xxh32(bytes, 0x41_54_54_43),
        alpha_pixels,
        non_default,
        distinct.len(),
        crop_counts
    )
}

fn depth_attachment_evidence_json(bytes: &[u8]) -> String {
    let mut finite = 0usize;
    let mut less_than_clear = 0usize;
    let mut min_depth = f32::INFINITY;
    let mut max_depth = f32::NEG_INFINITY;
    for chunk in bytes.chunks_exact(4) {
        let value = f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
        if value.is_finite() {
            finite += 1;
            min_depth = min_depth.min(value);
            max_depth = max_depth.max(value);
            if value < 0.999 {
                less_than_clear += 1;
            }
        }
    }
    if finite == 0 {
        min_depth = 0.0;
        max_depth = 0.0;
    }
    format!(
        "{{\"present\":true,\"hash\":\"{:08x}\",\"finite_pixels\":{},\"less_than_clear_pixels\":{},\"min_depth\":{:.6},\"max_depth\":{:.6}}}",
        xxh32(bytes, 0x44_45_50_54),
        finite,
        less_than_clear,
        min_depth,
        max_depth
    )
}

fn shader_mesh_perturbation_evidence_json(
    _width: u32,
    _height: u32,
    frame: &RuntimeRenderResult,
) -> String {
    let Some(albedo) = frame.attachments.get("albedo") else {
        return "{}".to_string();
    };
    let Some(normal) = frame.attachments.get("normal") else {
        return "{}".to_string();
    };
    let Some(material_light) = frame.attachments.get("material_light") else {
        return "{}".to_string();
    };
    let baseline = cpu_composite_g_buffer(albedo, normal, material_light);
    let mut darker_albedo = albedo.clone();
    for px in darker_albedo.chunks_exact_mut(4) {
        px[0] /= 2;
        px[1] /= 2;
        px[2] /= 2;
    }
    let mut flat_normal = normal.clone();
    for px in flat_normal.chunks_exact_mut(4) {
        px[0] = 128;
        px[1] = 128;
        px[2] = 255;
    }
    let mut dim_light = material_light.clone();
    for px in dim_light.chunks_exact_mut(4) {
        px[1] = 0;
        px[2] = 0;
    }
    let albedo_variant = cpu_composite_g_buffer(&darker_albedo, normal, material_light);
    let normal_variant = cpu_composite_g_buffer(albedo, &flat_normal, material_light);
    let light_variant = cpu_composite_g_buffer(albedo, normal, &dim_light);
    format!(
        "{{\"method\":\"bounded CPU replay of the same minimal composite equation\",\"baseline_hash\":\"{:08x}\",\"albedo_perturbation\":{},\"normal_perturbation\":{},\"material_light_perturbation\":{}}}",
        xxh32(&baseline, 0x43_4f_4d_50),
        perturbation_json(&baseline, &albedo_variant),
        perturbation_json(&baseline, &normal_variant),
        perturbation_json(&baseline, &light_variant)
    )
}

fn shader_mesh_composite_chain_evidence_json(frame: &RuntimeRenderResult) -> String {
    let hash = |name: &str, seed: u32| -> Option<u32> {
        frame.attachments.get(name).map(|bytes| xxh32(bytes, seed))
    };
    let changed = |left: &str, right: &str| -> usize {
        let Some(a) = frame.attachments.get(left) else {
            return 0;
        };
        let Some(b) = frame.attachments.get(right) else {
            return 0;
        };
        a.chunks_exact(4)
            .zip(b.chunks_exact(4))
            .filter(|(a, b)| {
                a[0].abs_diff(b[0]) > 2 || a[1].abs_diff(b[1]) > 2 || a[2].abs_diff(b[2]) > 2
            })
            .count()
    };
    let deferred_hash = hash("deferred_lit", 0x44_45_46_52).unwrap_or(0);
    let composite0_hash = hash("composite_0", 0x43_4f_4d_30).unwrap_or(0);
    let composite1_hash = hash("composite_1", 0x43_4f_4d_31).unwrap_or(0);
    let final_hash = hash("final_composite", 0x46_49_4e_41).unwrap_or(0);
    let deferred_to_composite0 = changed("deferred_lit", "composite_0");
    let composite0_to_composite1 = changed("composite_0", "composite_1");
    let composite1_to_final = changed("composite_1", "final_composite");
    format!(
        "{{\"deferred_lit_hash\":\"{:08x}\",\"composite_0_hash\":\"{:08x}\",\"composite_1_hash\":\"{:08x}\",\"final_hash\":\"{:08x}\",\"deferred_to_composite_0_changed_pixels\":{},\"composite_0_to_composite_1_changed_pixels\":{},\"composite_1_to_final_changed_pixels\":{},\"final_reads_last_configured_pass\":{}}}",
        deferred_hash,
        composite0_hash,
        composite1_hash,
        final_hash,
        deferred_to_composite0,
        composite0_to_composite1,
        composite1_to_final,
        composite1_to_final == 0 && composite1_hash != 0 && final_hash != 0
    )
}

fn shader_mesh_shadow_evidence_json(
    _backend: RuntimeBackend,
    width: u32,
    height: u32,
    frames: &[RuntimeRenderResult],
) -> String {
    let mut shadow_depth_hashes = Vec::new();
    let mut final_hashes = Vec::new();
    let mut less_than_clear = Vec::new();
    let mut final_delta_pixels = Vec::new();
    let mut shadowed_material_pixels = Vec::new();
    for frame in frames {
        if let Some(shadow_depth) = frame.attachments.get("shadow_depth") {
            shadow_depth_hashes.push(format!("\"{:08x}\"", xxh32(shadow_depth, 0x53_48_41_44)));
            let mut count = 0usize;
            for chunk in shadow_depth.chunks_exact(4) {
                let value = f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
                if value.is_finite() && value < 0.999 {
                    count += 1;
                }
            }
            less_than_clear.push(count);
        }
        shadowed_material_pixels.push(shadowed_material_pixel_count(frame, width, height));
        if let Some(final_composite) = frame.attachments.get("final_composite") {
            final_hashes.push(format!("\"{:08x}\"", xxh32(final_composite, 0x46_49_4e_53)));
            let mut count = 0usize;
            for px in final_composite.chunks_exact(4) {
                if px[0] < 12 && px[1] < 35 && px[2] < 205 {
                    count += 1;
                }
            }
            final_delta_pixels.push(count);
        }
    }
    let unique_shadow_hashes = shadow_depth_hashes
        .iter()
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    let unique_final_hashes = final_hashes
        .iter()
        .collect::<std::collections::BTreeSet<_>>()
        .len();
    format!(
        "{{\"shadow_depth_hashes\":[{}],\"final_hashes\":[{}],\"shadow_depth_less_than_clear\":{:?},\"shadowed_material_pixels\":{:?},\"final_shadow_candidate_pixels\":{:?},\"moving_shadow_depth_hashes\":{},\"moving_final_hashes\":{},\"shadowing_enabled\":true,\"shadow_bias\":0.006,\"shadow_darkening_factor\":0.42}}",
        shadow_depth_hashes.join(","),
        final_hashes.join(","),
        less_than_clear,
        shadowed_material_pixels,
        final_delta_pixels,
        unique_shadow_hashes,
        unique_final_hashes
    )
}

fn shadowed_material_pixel_count(
    frame: &RuntimeRenderResult,
    width: u32,
    height: u32,
) -> usize {
    let Some(world_position) = frame.attachments.get("world_position") else {
        return 0;
    };
    let Some(material_light) = frame.attachments.get("material_light") else {
        return 0;
    };
    let Some(shadow_depth) = frame.attachments.get("shadow_depth") else {
        return 0;
    };
    let light = shadow_light_view_projection_matrix();
    let shadow_params = shader_shadow_params(true);
    let mut shadowed = 0usize;
    for y in 0..height {
        for x in 0..width {
            let index = ((y * width + x) * 4) as usize;
            if material_light.get(index + 3).copied().unwrap_or(0) < 128 {
                continue;
            }
            // Match MINIMAL_DEFERRED_LIGHTING_FRAGMENT: packed world
            // coordinates are expanded by the explicit shadow domain
            // before applying the light projection.
            let shadow_range = shadow_params[3].max(1.0);
            let wx = (f32::from(world_position[index]) / 255.0 * 2.0 - 1.0) * shadow_range;
            let wy = (f32::from(world_position[index + 1]) / 255.0 * 2.0 - 1.0) * shadow_range;
            let wz = (f32::from(world_position[index + 2]) / 255.0 * 2.0 - 1.0) * shadow_range;
            let light_clip = [
                light[0] * wx + light[4] * wy + light[8] * wz + light[12],
                light[1] * wx + light[5] * wy + light[9] * wz + light[13],
                light[2] * wx + light[6] * wy + light[10] * wz + light[14],
                light[3] * wx + light[7] * wy + light[11] * wz + light[15],
            ];
            let inv_w = 1.0 / light_clip[3].abs().max(0.0001);
            let light_ndc = [
                light_clip[0] * inv_w,
                light_clip[1] * inv_w,
                light_clip[2] * inv_w,
            ];
            let shadow_u = light_ndc[0] * 0.5 + 0.5;
            let shadow_v = light_ndc[1] * 0.5 + 0.5;
            if !(0.0..=1.0).contains(&shadow_u) || !(0.0..=1.0).contains(&shadow_v) {
                continue;
            }
            let sx = ((shadow_u * width as f32).floor() as u32).min(width - 1);
            let sy = ((shadow_v * height as f32).floor() as u32).min(height - 1);
            let depth_index = ((sy * width + sx) * 4) as usize;
            let sampled_depth = f32::from_le_bytes([
                shadow_depth[depth_index],
                shadow_depth[depth_index + 1],
                shadow_depth[depth_index + 2],
                shadow_depth[depth_index + 3],
            ]);
            let compare_depth = light_ndc[2] * 0.5 + 0.5;
            if sampled_depth.is_finite() && compare_depth - shadow_params[1] > sampled_depth {
                shadowed += 1;
            }
        }
    }
    shadowed
}

fn perturbation_json(baseline: &[u8], variant: &[u8]) -> String {
    let changed = baseline
        .chunks_exact(4)
        .zip(variant.chunks_exact(4))
        .filter(|(a, b)| {
            a[0].abs_diff(b[0]) > 2 || a[1].abs_diff(b[1]) > 2 || a[2].abs_diff(b[2]) > 2
        })
        .count();
    format!(
        "{{\"variant_hash\":\"{:08x}\",\"changed_pixels\":{},\"final_changes\":{}}}",
        xxh32(variant, 0x50_45_52_54),
        changed,
        changed > 0
    )
}

fn cpu_composite_g_buffer(albedo: &[u8], normal: &[u8], material_light: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(albedo.len());
    for ((a, n), ml) in albedo
        .chunks_exact(4)
        .zip(normal.chunks_exact(4))
        .zip(material_light.chunks_exact(4))
    {
        if ml[3] < 128 {
            out.extend_from_slice(a);
            continue;
        }
        let nx = f32::from(n[0]) / 127.5 - 1.0;
        let ny = f32::from(n[1]) / 127.5 - 1.0;
        let nz = f32::from(n[2]) / 127.5 - 1.0;
        let normal_len = (nx * nx + ny * ny + nz * nz).sqrt().max(0.0001);
        let dot =
            ((nx / normal_len) * 0.35 + (ny / normal_len) * 0.65 + (nz / normal_len) * 0.68)
                / (0.35_f32 * 0.35 + 0.65 * 0.65 + 0.68 * 0.68).sqrt();
        let face = dot.clamp(0.18, 1.0);
        let light = ((f32::from(ml[1].max(ml[2])) / 255.0) * 0.75 + 0.25).clamp(0.2, 1.0);
        out.push((f32::from(a[0]) * face * light).round().clamp(0.0, 255.0) as u8);
        out.push((f32::from(a[1]) * face * light).round().clamp(0.0, 255.0) as u8);
        out.push((f32::from(a[2]) * face * light).round().clamp(0.0, 255.0) as u8);
        out.push(a[3]);
    }
    out
}

fn depth_attachment_to_grayscale_rgba(bytes: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(bytes.len());
    for chunk in bytes.chunks_exact(4) {
        let value = f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
        let normalized = if value.is_finite() {
            (1.0 - value.clamp(0.0, 1.0)) * 255.0
        } else {
            0.0
        };
        let gray = normalized.round().clamp(0.0, 255.0) as u8;
        out.extend_from_slice(&[gray, gray, gray, 255]);
    }
    out
}

fn write_png(path: &std::path::Path, width: u32, height: u32, pixels: &[u8]) -> GalResult<()> {
    let file = std::fs::File::create(path).map_err(|error| {
        GalError::backend(format!("failed to create PNG {}: {error}", path.display()))
    })?;
    let mut encoder = png::Encoder::new(file, width, height);
    encoder.set_color(png::ColorType::Rgba);
    encoder.set_depth(png::BitDepth::Eight);
    let mut writer = encoder
        .write_header()
        .map_err(|error| GalError::backend(format!("failed to write PNG header: {error}")))?;
    writer
        .write_image_data(pixels)
        .map_err(|error| GalError::backend(format!("failed to write PNG pixels: {error}")))
}

fn write_crop(
    path: &std::path::Path,
    source_width: u32,
    pixels: &[u8],
    crop: Crop,
) -> GalResult<()> {
    let mut cropped = Vec::with_capacity((crop.width * crop.height * 4) as usize);
    for y in crop.y..crop.y + crop.height {
        let start = ((y * source_width + crop.x) * 4) as usize;
        let end = start + (crop.width * 4) as usize;
        cropped.extend_from_slice(&pixels[start..end]);
    }
    write_png(path, crop.width, crop.height, &cropped)
}

fn write_side_by_side_png(
    path: &std::path::Path,
    width: u32,
    height: u32,
    left: &[u8],
    right: &[u8],
) -> GalResult<()> {
    let expected = (width as usize)
        .checked_mul(height as usize)
        .and_then(|pixels| pixels.checked_mul(4))
        .ok_or_else(|| GalError::backend("side-by-side image dimensions overflow"))?;
    if left.len() != expected || right.len() != expected {
        return Err(GalError::backend(
            "side-by-side images do not match expected dimensions",
        ));
    }
    let combined_width = width * 2;
    let mut pixels = Vec::with_capacity((combined_width * height * 4) as usize);
    for y in 0..height {
        let row_start = (y * width * 4) as usize;
        let row_end = row_start + (width * 4) as usize;
        pixels.extend_from_slice(&left[row_start..row_end]);
        pixels.extend_from_slice(&right[row_start..row_end]);
    }
    write_png(path, combined_width, height, &pixels)
}

#[test]
fn depth_history_becomes_valid_only_after_exact_submission_confirmation() {
    let mut frontend = WorldPrimitiveFrontend::default();
    let first = GBufferDepthHistorySubmission {
        frame_id: 41,
        graph_generation: 7,
        prior_before_translucency_valid: false,
    };
    assert!(!frontend.g_buffer_depth_history.before_translucency_valid);
    assert!(!frontend.g_buffer_depth_history.previous_valid);

    frontend
        .confirm_g_buffer_depth_history_submission(first, SubmissionId(91), 7)
        .unwrap();
    assert_eq!(7, frontend.g_buffer_depth_history.graph_generation);
    assert!(frontend.g_buffer_depth_history.before_translucency_valid);
    assert!(!frontend.g_buffer_depth_history.previous_valid);
    assert_eq!(Some(41), frontend.g_buffer_depth_history.last_frame_id);
    assert_eq!(
        Some(SubmissionId(91)),
        frontend.g_buffer_depth_history.last_submission
    );

    frontend
        .confirm_g_buffer_depth_history_submission(
            GBufferDepthHistorySubmission {
                frame_id: 42,
                graph_generation: 7,
                prior_before_translucency_valid: true,
            },
            SubmissionId(92),
            7,
        )
        .unwrap();
    assert!(frontend.g_buffer_depth_history.previous_valid);
    assert_eq!(Some(42), frontend.g_buffer_depth_history.last_frame_id);
    assert_eq!(
        Some(SubmissionId(92)),
        frontend.g_buffer_depth_history.last_submission
    );

    let before_rejection = frontend.g_buffer_depth_history;
    let error = frontend
        .confirm_g_buffer_depth_history_submission(
            GBufferDepthHistorySubmission {
                frame_id: 43,
                graph_generation: 7,
                prior_before_translucency_valid: true,
            },
            SubmissionId(93),
            8,
        )
        .unwrap_err();
    assert!(error.to_string().contains("graph generation changed"));
    assert_eq!(before_rejection, frontend.g_buffer_depth_history);
}

fn repo_root() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(|path| path.parent())
        .and_then(|path| path.parent())
        .expect("rust crate should live under src/main/rust")
        .to_path_buf()
}

fn assert_environment_gap(error: &GalError, backend: &str) {
    let text = error.to_string();
    assert!(
        text.contains(backend)
            || text.contains("physical device")
            || text.contains("EGL")
            || text.contains("GLX")
            || text.contains("OpenGL")
            || text.contains("Vulkan"),
        "unexpected runtime material conformance failure: {text}"
    );
}

#[test]
fn selected_source_execution_env_override_parsing() {
    assert!(!WorldPrimitiveFrontend::selected_source_execution_env_enabled(None));
    assert!(!WorldPrimitiveFrontend::selected_source_execution_env_enabled(Some("")));
    assert!(!WorldPrimitiveFrontend::selected_source_execution_env_enabled(Some("0")));
    assert!(!WorldPrimitiveFrontend::selected_source_execution_env_enabled(Some("false")));
    assert!(WorldPrimitiveFrontend::selected_source_execution_env_enabled(Some("1")));
    assert!(WorldPrimitiveFrontend::selected_source_execution_env_enabled(Some(" true ")));
    assert!(WorldPrimitiveFrontend::selected_source_execution_env_enabled(Some("ON")));
}

#[test]
fn source_execution_follows_the_selected_pack_with_env_override() {
    use crate::render::shaderpack::source::{ShaderPackSource, ShaderSourceFile};
    let pack = ShaderPackSource::new(
        "Pack.zip",
        3,
        vec![ShaderSourceFile::new("shaders.properties", "")],
    )
    .unwrap();
    let disabled = ShaderPackSource::new("disabled", 4, Vec::new()).unwrap();
    let post_effect = ShaderPackSource::new(
        "minecraft-resource-pack:minecraft:transparency",
        5,
        vec![ShaderSourceFile::new("shaders.properties", "")],
    )
    .unwrap();
    // No override: a selected pack executes; no pack, disabled, or a
    // vanilla post effect does not (and retains no second mesh copy).
    assert!(WorldPrimitiveFrontend::source_execution_decision(None, Some(&pack)));
    assert!(!WorldPrimitiveFrontend::source_execution_decision(None, None));
    assert!(!WorldPrimitiveFrontend::source_execution_decision(None, Some(&disabled)));
    assert!(!WorldPrimitiveFrontend::source_execution_decision(None, Some(&post_effect)));
    // The environment variable overrides the configuration both ways.
    assert!(!WorldPrimitiveFrontend::source_execution_decision(Some("0"), Some(&pack)));
    assert!(!WorldPrimitiveFrontend::source_execution_decision(Some(""), Some(&pack)));
    assert!(WorldPrimitiveFrontend::source_execution_decision(Some("1"), None));
}

#[test]
fn mesh_batch_plan_key_tracks_topology_but_not_frame_local_transforms() {
    let mut frame = frame(Vec::new());
    let mut instance = mesh_instance(9182, 1);
    instance.stratum = WORLD_STRATUM_ENTITY_MESH;
    frame.mesh_instances.push(instance);
    let first = mesh_batch_plan_key(
        &frame,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    );
    frame.mesh_instances[0].transform[12] = 42.0;
    frame.mesh_instances[0].color_argb = 0x8040_2010;
    let moved = mesh_batch_plan_key(
        &frame,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    );
    assert_eq!(first, moved);

    frame.mesh_instances[0].flags = WORLD_MESH_INSTANCE_FLAG_CAMERA_SORTED_QUADS;
    let camera_sorted = mesh_batch_plan_key(
        &frame,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    );
    assert_ne!(first, camera_sorted);

    frame.mesh_instances[0].stratum = WORLD_STRATUM_TERRAIN;
    frame.mesh_instances[0].flags = 0;
    let terrain_facing = mesh_batch_plan_key(
        &frame,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    );
    frame.mesh_instances[0].terrain_visible_facing_mask = (1 << 0) | (1 << 6);
    let turned_terrain = mesh_batch_plan_key(
        &frame,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    );
    assert_ne!(terrain_facing, turned_terrain);
}

#[test]
fn settled_mesh_batch_cache_hit_reuses_identity_staging_capacity() {
    let mut gal = gal();
    let target = frame_target(&mut gal, 1, 128, 128);
    let mut frontend = WorldPrimitiveFrontend::default();
    frontend
        .apply_world_mesh_asset_update(
            &mut gal,
            1,
            vec![mesh_asset(9182, 1, IndexType::U32)],
            Vec::new(),
        )
        .unwrap();
    let mut first = frame(Vec::new());
    first.mesh_instances = (0..64)
        .map(|section| {
            let mut instance = mesh_instance(9182, 1);
            instance.transform[12] = section as f32 * 16.0;
            instance
        })
        .collect();
    frontend
        .append_frame_ops(&mut gal, 1, target, first.clone())
        .unwrap();
    assert_eq!(1, frontend.mesh_batch_plan_cache.len());
    assert_eq!(64, frontend.mesh_batch_identity_scratch.len());
    let scratch_allocation = frontend.mesh_batch_identity_scratch.as_ptr();
    let scratch_capacity = frontend.mesh_batch_identity_scratch.capacity();

    let mut moved = first;
    moved.frame_id = 2;
    for instance in &mut moved.mesh_instances {
        instance.transform[14] -= 0.25;
    }
    frontend
        .append_frame_ops(&mut gal, 2, target, moved)
        .unwrap();

    assert_eq!(1, frontend.mesh_batch_plan_cache.len());
    assert_eq!(64, frontend.mesh_batch_identity_scratch.len());
    assert_eq!(
        scratch_capacity,
        frontend.mesh_batch_identity_scratch.capacity()
    );
    assert_eq!(
        scratch_allocation,
        frontend.mesh_batch_identity_scratch.as_ptr()
    );
}

#[test]
fn camera_sorted_terrain_interleaves_materials_and_invalidates_replaced_geometry() {
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    let mut mesh = mesh_asset(9182, 1, IndexType::U32);
    let template = mesh.vertices[..4].to_vec();
    mesh.vertices.clear();
    mesh.index_bytes.clear();
    mesh.sections.clear();
    for (quad, z) in [1., 3., 2.].into_iter().enumerate() {
        for vertex in &template {
            let mut vertex = *vertex;
            vertex.position[2] = z;
            mesh.vertices.push(vertex);
        }
        for lane in [0, 1, 2, 2, 3, 0] {
            mesh.index_bytes
                .extend_from_slice(&((quad * 4 + lane) as u32).to_ne_bytes());
        }
        mesh.sections.push(WorldMeshSection {
            material_id: if quad == 2 {
                WORLD_MATERIAL_ID_WATER_TRANSLUCENT
            } else {
                WORLD_MATERIAL_ID_TRANSLUCENT_TEXTURED
            },
            texture_id: WORLD_MESH_TEXTURE_TERRAIN_BLOCK_ATLAS,
            material_mode: WORLD_MATERIAL_MODE_TRANSLUCENT,
            cull_policy: WORLD_CULL_BACK,
            winding: WORLD_WINDING_CCW,
            index_offset: quad as u32 * 24,
            index_count: 6,
            source_facing: 6,
        });
    }
    let mut replacement = mesh.clone();
    frontend
        .apply_world_mesh_asset_update(
            &mut gal,
            1,
            vec![mesh, mesh_asset(9183, 1, IndexType::U16)],
            Vec::new(),
        )
        .unwrap();
    let mut instance = mesh_instance(9182, 1);
    instance.stratum = WORLD_STRATUM_TERRAIN;
    instance.mesh_section_index = WORLD_MESH_SECTION_ALL;
    instance.depth_policy = WORLD_DEPTH_POLICY_TEST_NO_WRITE;
    instance.flags = WORLD_MESH_INSTANCE_FLAG_CAMERA_SORTED_QUADS;
    // Frozen's vanilla translucent pipeline writes depth. Sorting must be
    // requested by semantic layer, not inferred from disabled depth writes.
    instance.depth_policy = WORLD_DEPTH_POLICY_TEST_WRITE;
    instance.transform = matrix4_identity();
    instance.transform[14] = -5.;
    let mut frame = frame(Vec::new());
    frame.mesh_instances.push(instance);
    let batches = mesh_batches(
        &frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    )
    .unwrap();
    assert_eq!(
        batches.iter().map(|b| b.index_offset).collect::<Vec<_>>(),
        vec![0, 48, 24]
    );
    assert_eq!(
        batches
            .iter()
            .map(|b| b.key.material_id)
            .collect::<Vec<_>>(),
        vec![
            WORLD_MATERIAL_ID_TRANSLUCENT_TEXTURED,
            WORLD_MATERIAL_ID_WATER_TRANSLUCENT,
            WORLD_MATERIAL_ID_TRANSLUCENT_TEXTURED
        ]
    );
    assert_eq!(batches.iter().map(|b| b.index_count).sum::<u32>(), 18);
    let mut sorted_indices = Vec::new();
    let sorted_batches = mesh_batches_selected_with_sorted_indices(
        &frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
        MeshBatchSelection::CameraSorted,
        Some(&mut sorted_indices),
    )
    .unwrap();
    assert_eq!(
        sorted_batches
            .iter()
            .map(|batch| batch.sorted_index_offset)
            .collect::<Vec<_>>(),
        vec![Some(0), Some(24), Some(48)]
    );
    assert_eq!(
        sorted_batches
            .iter()
            .map(|batch| batch.key.material_id)
            .collect::<Vec<_>>(),
        batches
            .iter()
            .map(|batch| batch.key.material_id)
            .collect::<Vec<_>>()
    );
    let original_indices = &frontend.mesh_assets[&9182].index_bytes;
    assert_eq!(&sorted_indices[0..24], &original_indices[0..24]);
    assert_eq!(&sorted_indices[24..48], &original_indices[48..72]);
    assert_eq!(&sorted_indices[48..72], &original_indices[24..48]);
    assert_eq!(
        sorted_batches
            .iter()
            .map(|batch| batch.index_count)
            .sum::<u32>(),
        18
    );
    let mut shifted_frame = frame.clone();
    shifted_frame.mesh_instances.insert(0, mesh_instance(9183, 1));
    let mut shifted_indices = vec![0xaa; 4];
    let shifted_batches = mesh_batches_selected_with_sorted_indices(
        &shifted_frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
        MeshBatchSelection::CameraSorted,
        Some(&mut shifted_indices),
    )
    .unwrap();
    assert_eq!(&shifted_indices[4..], sorted_indices.as_slice());
    assert_eq!(shifted_batches.len(), sorted_batches.len());
    for (original, shifted) in sorted_batches.iter().zip(&shifted_batches) {
        assert_eq!(shifted.indices.as_slice(), &[1]);
        assert_eq!(shifted.index_count, original.index_count);
        assert_eq!(shifted.key, original.key);
        assert_eq!(
            shifted.sorted_index_offset,
            original.sorted_index_offset.map(|offset| offset + 4)
        );
    }
    assert!(geometry::translucent_order::has_direct_template(&frontend.mesh_assets[&9182]));
    // Camera z 5 -> 6 stays beyond every pane: same plane-arrangement
    // cell, so the sorted order (and its template) is reused exactly.
    shifted_frame.mesh_instances[1].transform[14] = -6.;
    let mut same_cell_indices = Vec::new();
    mesh_batches_selected_with_sorted_indices(
        &shifted_frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
        MeshBatchSelection::CameraSorted,
        Some(&mut same_cell_indices),
    )
    .unwrap();
    assert!(geometry::translucent_order::has_direct_template(&frontend.mesh_assets[&9182]));
    assert_eq!(same_cell_indices.as_slice(), sorted_indices.as_slice());
    // Between panes (z 2.5) is another cell: re-sort, drop the template.
    shifted_frame.mesh_instances[1].transform[14] = -2.5;
    let mut moved_indices = Vec::new();
    let moved_batches = mesh_batches_selected_with_sorted_indices(
        &shifted_frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
        MeshBatchSelection::CameraSorted,
        Some(&mut moved_indices),
    )
    .unwrap();
    assert!(!geometry::translucent_order::has_direct_template(&frontend.mesh_assets[&9182]));
    assert_ne!(moved_indices.as_slice(), sorted_indices.as_slice());
    let mut repeated_indices = Vec::new();
    let repeated_batches = mesh_batches_selected_with_sorted_indices(
        &shifted_frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
        MeshBatchSelection::CameraSorted,
        Some(&mut repeated_indices),
    )
    .unwrap();
    assert!(geometry::translucent_order::has_direct_template(&frontend.mesh_assets[&9182]));
    assert_eq!(moved_indices, repeated_indices);
    assert_eq!(moved_batches.len(), repeated_batches.len());
    let page_stream = packed_mesh_draw_stream(
        &frame,
        &frontend,
        &batches,
        required_mesh_instance_stream_bytes(&batches).unwrap(),
        true,
        true,
    )
    .unwrap();
    assert_eq!(page_stream.first_instances, vec![Some(0), Some(1), Some(2)]);
    let ordinary_stream = packed_mesh_draw_stream(
        &frame,
        &frontend,
        &batches,
        required_mesh_instance_stream_bytes(&batches).unwrap(),
        true,
        false,
    )
    .unwrap();
    assert_eq!(ordinary_stream.first_instances, vec![None; 3]);
    assert!(frontend.mesh_assets[&9182]
        .translucent_order
        .borrow()
        .is_some());
    // Reusing the camera-order cache for another target must preserve
    // semantic order while producing orientation-specific bindings.
    let down = mesh_batches(
        &frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Down,
        false,
        false,
    )
    .unwrap();
    assert_eq!(down.len(), batches.len());
    for (up, down) in batches.iter().zip(&down) {
        assert_eq!(down.key.raster_y_direction, RasterYDirection::Down);
        assert_eq!(down.key.geometry_key(), up.key.geometry_key());
        assert_eq!(down.index_offset, up.index_offset);
        assert_eq!(down.index_count, up.index_count);
        assert_eq!(down.indices, up.indices);
        let mut normalized = down.key;
        normalized.raster_y_direction = RasterYDirection::Up;
        assert_eq!(normalized, up.key);
    }

    // One dynamic translucent section must not make the stable opaque
    // topology uncacheable. Recombining a cached static plan with only
    // the freshly sorted subset must be byte-for-byte equivalent at the
    // semantic batch boundary to a complete rebuild.
    let mut mixed = frame.clone();
    mixed.mesh_instances.clear();
    mixed.mesh_instances.push(mesh_instance(9183, 1));
    mixed.mesh_instances.push(frame.mesh_instances[0].clone());
    let full = mesh_batches(
        &mixed,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    )
    .unwrap();
    let static_batches = mesh_batches_selected(
        &mixed,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
        MeshBatchSelection::Static,
    )
    .unwrap();
    let dynamic_batches = mesh_batches_selected(
        &mixed,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
        MeshBatchSelection::CameraSorted,
    )
    .unwrap();
    assert!(static_batches
        .iter()
        .all(|batch| batch.indices.iter().all(|index| *index == 0)));
    assert!(dynamic_batches
        .iter()
        .all(|batch| batch.indices.iter().all(|index| *index == 1)));
    let mut recombined = static_batches;
    recombined.extend(dynamic_batches);
    sort_mesh_batches(&mut recombined, &mixed);
    assert_eq!(full.len(), recombined.len());
    for (expected, actual) in full.iter().zip(&recombined) {
        assert_eq!(
            expected.model_submission_order,
            actual.model_submission_order
        );
        assert_eq!(expected.key, actual.key);
        assert_eq!(expected.index_offset, actual.index_offset);
        assert_eq!(expected.index_count, actual.index_count);
        assert_eq!(expected.indices, actual.indices);
    }
    // Camera movement re-evaluates order without mutating the source bytes.
    frame.mesh_instances[0].transform[14] = 0.;
    let moved = mesh_batches(
        &frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    )
    .unwrap();
    assert_eq!(
        moved.iter().map(|b| b.index_offset).collect::<Vec<_>>(),
        vec![0, 24, 48]
    );
    let mut moved_sorted_indices = Vec::new();
    let moved_sorted = mesh_batches_selected_with_sorted_indices(
        &frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
        MeshBatchSelection::CameraSorted,
        Some(&mut moved_sorted_indices),
    )
    .unwrap();
    assert_eq!(moved_sorted.len(), 2);
    assert_eq!(
        moved_sorted
            .iter()
            .map(|b| b.index_count)
            .collect::<Vec<_>>(),
        vec![12, 6]
    );
    assert_eq!(
        moved_sorted_indices,
        frontend.mesh_assets[&9182].index_bytes
    );
    assert_eq!(
        frontend.mesh_assets[&9182].index_bytes,
        replacement.index_bytes
    );
    replacement.mesh_generation = 2;
    // A reload can retain the key and index layout while changing actual
    // geometry. Reusing the old cached positions would silently mis-sort it.
    for vertex in &mut replacement.vertices[..4] {
        vertex.position[2] = 4.;
    }
    frontend
        .apply_world_mesh_asset_update(&mut gal, 2, vec![replacement], Vec::new())
        .unwrap();
    assert!(frontend.mesh_assets[&9182]
        .translucent_order
        .borrow()
        .is_none());
    assert!(mesh_batches(
        &frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false
    )
    .is_err());
    frame.mesh_instances[0].mesh_generation = 2;
    frame.mesh_instances[0].transform[14] = -5.;
    let reloaded = mesh_batches(
        &frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    )
    .unwrap();
    assert_eq!(
        reloaded.iter().map(|b| b.index_offset).collect::<Vec<_>>(),
        vec![48, 24, 0]
    );
    assert!(frontend.mesh_assets[&9182]
        .translucent_order
        .borrow()
        .is_some());
    frontend
        .apply_world_mesh_asset_update_with_sorted_and_retirements(
            &mut gal,
            3,
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![(9182, 2)],
        )
        .unwrap();
    assert!(!frontend.mesh_assets.contains_key(&9182));
    assert!(mesh_batches(
        &frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false
    )
    .is_err());
}

#[test]
fn model_submission_order_prevents_cross_order_resource_merging() {
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    let opaque = mesh_asset(182, 1, IndexType::U16);
    let mut translucent = mesh_asset(183, 1, IndexType::U16);
    translucent.sections[0].material_mode = WORLD_MATERIAL_MODE_TRANSLUCENT;
    translucent.sections[0].material_id = WORLD_MATERIAL_ID_TRANSLUCENT_TEXTURED;
    frontend
        .apply_world_mesh_asset_update(&mut gal, 1, vec![opaque, translucent], Vec::new())
        .unwrap();
    let mut scene = frame(Vec::new());
    for (key, order) in [(182, 1), (183, 0), (182, -1), (182, 1)] {
        let mut value = mesh_instance(key, 1);
        value.stratum = WORLD_STRATUM_ENTITY_MESH;
        value.model_submission_order = Some(order);
        scene.mesh_instances.push(value);
    }
    let batches = mesh_batches(
        &scene,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    )
    .unwrap();
    assert_eq!(
        batches
            .iter()
            .map(|b| (b.key.mesh_key, b.model_submission_order, b.indices.to_vec()))
            .collect::<Vec<_>>(),
        vec![
            (182, Some(-1), vec![2]),
            (183, Some(0), vec![1]),
            (182, Some(1), vec![0, 3])
        ]
    );
}

#[test]
fn vulkan_armor_glint_survives_later_authored_equipment_overlay() {
    use crate::render::shared::item_foil::{StandardFoilKind, StandardItemFoil};
    for hand in [false, true] {
        for reverse in [false, true] {
            let backend = crate::render::vulkanic::test_support::vulkan_gal(
                "deferred armor glint overlap",
            )
            .unwrap();
            let mut gal = backend;
            let mut frontend = WorldPrimitiveFrontend::default();
            let vertices = || {
                [
                    [-0.5, -0.5, 0.0],
                    [0.5, -0.5, 0.0],
                    [0.5, 0.5, 0.0],
                    [-0.5, 0.5, 0.0],
                ]
                .into_iter()
                .map(|p| shader_mesh_vertex(p, [0.25, 0.75], 0xff000000, 0, [0.0, 0.0, 1.0]))
                .collect()
            };
            let mut assets = Vec::new();
            for key in [1001, 1002, 1003] {
                let foil = key == 1002;
                let mut asset = shader_mesh_quad_asset(
                    key,
                    1,
                    1001,
                    if foil {
                        WORLD_MATERIAL_ID_GLINT_TEXTURED
                    } else {
                        WORLD_MATERIAL_ID_OPAQUE_TEXTURED
                    },
                    if foil {
                        WORLD_MATERIAL_MODE_GLINT
                    } else {
                        WORLD_MATERIAL_MODE_OPAQUE
                    },
                    vertices(),
                );
                asset.sections[0].cull_policy = WORLD_CULL_NONE;
                assets.push(asset);
            }
            let mut png_bytes = Vec::new();
            {
                let mut encoder = png::Encoder::new(&mut png_bytes, 1, 1);
                encoder.set_color(png::ColorType::Rgba);
                encoder.set_depth(png::BitDepth::Eight);
                encoder
                    .write_header()
                    .unwrap()
                    .write_image_data(&[255; 4])
                    .unwrap();
            }
            let texture=WorldMeshTextureAssetPayload {texture_id:1001,png_bytes,mip_png_bytes:Vec::new(),
            frame_width:0,frame_height:0,frame_count:1,frame_ticks:1,animation_flags:0,frame_row_size:0,
            interpolation_policy:0,animation_frames:Vec::new(),coordinate_origin:0,
            sampling:Some(crate::render::shared::texture_sampling::TextureSampling::from_texture_metadata(true,false)),requested_mip_levels:1};
            frontend
                .apply_world_mesh_asset_update(&mut gal, 1, assets, vec![texture])
                .unwrap();
            let mut instances = Vec::new();
            for key in [1001, 1002, 1003] {
                let mut v = mesh_instance(key, 1);
                v.stratum = WORLD_STRATUM_ENTITY_MESH;
                v.cull_policy = WORLD_CULL_NONE;
                v.model_submission_order = Some((key - 1000) as i32);
                v.flags = crate::render::shared::view_layering::PERSPECTIVE_FLAG;
                if key == 1002 {
                    v.flags = 0;
                    v.depth_policy = WORLD_DEPTH_POLICY_TEST_NO_WRITE;
                    v.item_foil = Some(StandardItemFoil {
                        kind: StandardFoilKind::Armor,
                        clock_millis: 12345,
                        speed: 0.5,
                        strength: 0.5,
                    });
                }
                instances.push(v);
            }
            if reverse {
                instances.reverse();
            }
            let mut scene = frame(Vec::new());
            scene.background = WorldBackgroundRequest::default();
            scene.shader_environment.enabled = true;
            scene.shader_environment.far_plane = 128.0;
            scene.shader_environment.fog_environmental_start = 1.0e12;
            scene.shader_environment.fog_environmental_end = 1.0e12;
            scene.shader_environment.fog_render_distance_start = 1.0e12;
            scene.shader_environment.fog_render_distance_end = 1.0e12;
            if hand {
                scene.first_person = WorldFirstPersonFrame {
                    enabled: true,
                    clear_depth_before: true,
                    main_hand_instance_count: 3,
                    projection_matrix: scene.projection_matrix,
                    translucent_hand_mask: 0,
                    model_view_matrix: scene.view_matrix,
                };
                scene.first_person_mesh_instances = instances;
            } else {
                scene.mesh_instances = instances;
            }
            let rendered = render_material_scene(
                &mut gal,
                &mut frontend,
                1,
                128,
                128,
                scene,
                "deferred-armor-glint",
            )
            .unwrap();
            for y in 60..68 {
                for x in 60..68 {
                    let pixel = &rendered.pixels[(y * 128 + x) * 4..(y * 128 + x) * 4 + 4];
                    // White glint at strength .5 contributes .5 squared through SRC_COLOR blend.
                    for channel in &pixel[..3] {
                        assert!(
                            (*channel as i16 - 64).abs() <= 1,
                            "hand={hand} reverse={reverse}: {pixel:?}"
                        );
                    }
                    assert_eq!(pixel[3], 255);
                }
            }
            frontend.reset(&mut gal);
        }
    }
}

#[test]
fn model_submission_order_defers_armor_glint_after_all_authored_layers() {
    use crate::render::shared::item_foil::{StandardFoilKind, StandardItemFoil};
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    let base = mesh_asset(182, 1, IndexType::U16);
    let mut foil = mesh_asset(183, 1, IndexType::U16);
    foil.sections[0].material_mode = WORLD_MATERIAL_MODE_GLINT;
    foil.sections[0].material_id = WORLD_MATERIAL_ID_GLINT_TEXTURED;
    frontend
        .apply_world_mesh_asset_update(&mut gal, 1, vec![base, foil], Vec::new())
        .unwrap();
    for reverse in [false, true] {
        let mut scene = frame(Vec::new());
        for (key, order) in [(182, i32::MIN), (183, 2), (182, i32::MAX)] {
            let mut value = mesh_instance(key, 1);
            value.stratum = WORLD_STRATUM_ENTITY_MESH;
            value.model_submission_order = Some(order);
            if key == 183 {
                value.item_foil = Some(StandardItemFoil {
                    kind: StandardFoilKind::Armor,
                    clock_millis: 0,
                    speed: 0.5,
                    strength: 0.5,
                });
            }
            scene.mesh_instances.push(value);
        }
        if reverse {
            scene.mesh_instances.reverse();
        }
        let batches = mesh_batches(
            &scene,
            &frontend,
            ColorFormat::Bgra8Unorm,
            RasterYDirection::Up,
            false,
            false,
        )
        .unwrap();
        assert_eq!(
            batches
                .iter()
                .map(|b| (b.key.mesh_key, b.model_submission_order))
                .collect::<Vec<_>>(),
            vec![(182, Some(i32::MIN)), (182, Some(i32::MAX)), (183, Some(2))]
        );
    }
}

#[test]
fn vulkan_model_submission_order_controls_coincident_alpha_and_cutout_layers() {
    for (alpha_order, red_order, red_visible) in [(0, 1, true), (1, 0, false)] {
        for reverse_arrival in [false, true] {
            let backend = crate::render::vulkanic::test_support::vulkan_gal(
                "model order overlap",
            )
            .unwrap();
            let mut gal = backend;
            let mut frontend = WorldPrimitiveFrontend::default();
            let vertices = |color| {
                [
                    [-0.5, -0.5, 0.],
                    [0.5, -0.5, 0.],
                    [0.5, 0.5, 0.],
                    [-0.5, 0.5, 0.],
                ]
                .into_iter()
                .map(|p| shader_mesh_vertex(p, [0.5, 0.5], color, 0, [0., 1., 0.]))
                .collect()
            };
            let mut red = shader_mesh_quad_asset(
                1001,
                1,
                1001,
                WORLD_MATERIAL_ID_PER_FACE_MODEL_CUTOUT_TEXTURED,
                WORLD_MATERIAL_MODE_CUTOUT,
                vertices(0xffff0000),
            );
            let mut alpha = shader_mesh_quad_asset(
                1002,
                1,
                1001,
                WORLD_MATERIAL_ID_PER_FACE_TRANSLUCENT_CUTOUT_TEXTURED,
                WORLD_MATERIAL_MODE_TRANSLUCENT_CUTOUT,
                vertices(0x800000ff),
            );
            red.sections[0].cull_policy = WORLD_CULL_NONE;
            alpha.sections[0].cull_policy = WORLD_CULL_NONE;
            let mut png_bytes = Vec::new();
            {
                let mut encoder = png::Encoder::new(&mut png_bytes, 1, 1);
                encoder.set_color(png::ColorType::Rgba);
                encoder.set_depth(png::BitDepth::Eight);
                encoder
                    .write_header()
                    .unwrap()
                    .write_image_data(&[255, 255, 255, 255])
                    .unwrap();
            }
            let texture = WorldMeshTextureAssetPayload {
                texture_id: 1001,
                png_bytes,
                mip_png_bytes: Vec::new(),
                frame_width: 0,
                frame_height: 0,
                frame_count: 1,
                frame_ticks: 1,
                animation_flags: 0,
                frame_row_size: 0,
                interpolation_policy: 0,
                animation_frames: Vec::new(),
                coordinate_origin: 0,
                sampling: None,
                requested_mip_levels: 1,
            };
            frontend
                .apply_world_mesh_asset_update(&mut gal, 1, vec![red, alpha], vec![texture])
                .unwrap();
            let mut red = mesh_instance(1001, 1);
            red.stratum = WORLD_STRATUM_ENTITY_MESH;
            red.cull_policy = WORLD_CULL_NONE;
            red.model_submission_order = Some(red_order);
            let mut alpha = red.clone();
            alpha.mesh_key = 1002;
            alpha.model_submission_order = Some(alpha_order);
            let mut scene = frame(Vec::new());
            scene.background = WorldBackgroundRequest::default();
            scene.mesh_instances = if reverse_arrival {
                vec![alpha, red]
            } else {
                vec![red, alpha]
            };
            let rendered = render_material_scene(
                &mut gal,
                &mut frontend,
                1,
                128,
                128,
                scene,
                "model-order-overlap",
            )
            .unwrap();
            let pixel = &rendered.pixels[(64 * 128 + 64) * 4..(64 * 128 + 64) * 4 + 4];
            assert!(
                pixel[0] > 30 && pixel[1] < 5,
                "unexpected layer color: {pixel:?}"
            );
            assert_eq!(pixel[2]<5,red_visible,"authored alpha={alpha_order},red={red_order},reverse={reverse_arrival}: {pixel:?}");
            frontend.reset(&mut gal);
        }
    }
}

#[test]
fn world_mesh_batches_submit_opaque_before_later_arriving_translucency() {
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    let opaque = mesh_asset(182, 1, IndexType::U16);
    let mut translucent = mesh_asset(183, 1, IndexType::U16);
    translucent.sections[0].material_mode = WORLD_MATERIAL_MODE_TRANSLUCENT;
    translucent.sections[0].material_id = WORLD_MATERIAL_ID_TRANSLUCENT_TEXTURED;
    frontend
        .apply_world_mesh_asset_update(&mut gal, 1, vec![opaque, translucent], Vec::new())
        .unwrap();
    let mut frame = frame(Vec::new());
    // Deliberately reverse producer arrival: the semantic batcher, not
    // incidental callback order, owns the vanilla render-phase contract.
    let mut translucent_instance = mesh_instance(183, 1);
    translucent_instance.depth_policy = WORLD_DEPTH_POLICY_TEST_NO_WRITE;
    frame.mesh_instances.push(translucent_instance);
    frame.mesh_instances.push(mesh_instance(182, 1));

    let batches = mesh_batches(
        &frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    )
    .expect("complete semantic mesh assets must batch");
    assert_eq!(
        vec![WORLD_MATERIAL_MODE_OPAQUE, WORLD_MATERIAL_MODE_TRANSLUCENT],
        batches
            .iter()
            .map(|batch| batch.key.material_mode)
            .collect::<Vec<_>>()
    );
}

#[test]
fn translucent_mesh_batches_preserve_non_adjacent_back_to_front_records() {
    let mut gal = gal();
    let mut frontend = WorldPrimitiveFrontend::default();
    let mut first = mesh_asset(184, 1, IndexType::U16);
    let mut second = mesh_asset(185, 1, IndexType::U16);
    for asset in [&mut first, &mut second] {
        asset.sections[0].material_mode = WORLD_MATERIAL_MODE_TRANSLUCENT;
        asset.sections[0].material_id = WORLD_MATERIAL_ID_TRANSLUCENT_TEXTURED;
    }
    frontend
        .apply_world_mesh_asset_update(&mut gal, 1, vec![first, second], Vec::new())
        .unwrap();
    let mut frame = frame(Vec::new());
    // This is the copied sorted stream: far A, middle B, near A. A
    // resource-key batcher must not fold the two A records together,
    // because that would draw the near pane before B.
    for mesh_key in [184, 185, 184] {
        let mut instance = mesh_instance(mesh_key, 1);
        instance.depth_policy = WORLD_DEPTH_POLICY_TEST_NO_WRITE;
        frame.mesh_instances.push(instance);
    }

    let batches = mesh_batches(
        &frame,
        &frontend,
        ColorFormat::Bgra8Unorm,
        RasterYDirection::Up,
        false,
        false,
    )
    .expect("complete translucent semantic mesh stream must batch");
    assert_eq!(
        vec![184, 185, 184],
        batches
            .iter()
            .map(|batch| batch.key.mesh_key)
            .collect::<Vec<_>>(),
        "non-adjacent translucent records must retain their submitted order"
    );
    assert_eq!(
        vec![vec![0], vec![1], vec![2]],
        batches
            .iter()
            .map(|batch| batch.indices.to_vec())
            .collect::<Vec<_>>()
    );
}

#[test]
fn direct_mesh_header_preserves_sodium_fog_alpha() {
    let mut frame = frame(Vec::new());
    frame.shader_environment.fog_parameter_color = [0.2, 0.4, 0.6, 0.75];
    let header = packed_mesh_uniform_header(&frame);
    assert_eq!(WORLD_MESH_BATCH_HEADER_BYTES, header.len());
    let fog_alpha_offset = header.len() - std::mem::size_of::<f32>();
    assert_eq!(
        0.75,
        f32::from_ne_bytes(header[fog_alpha_offset..].try_into().unwrap()),
        "the direct mesh stream must retain Sodium _linearFog's fogColor.a"
    );
}

