#[test]
fn empty_load_store_gui_passes_are_stripped_but_clearing_passes_are_kept() {
    let pass = Handle::new(crate::render::vulkanic::handles::HandleKind::RenderPass, 9, 1).unwrap();
    let target = Handle::new(crate::render::vulkanic::handles::HandleKind::RenderTarget, 10, 1).unwrap();
    let attachment = |load_op| PassAttachment {
        view: Handle::new(crate::render::vulkanic::handles::HandleKind::TextureView, 11, 1).unwrap(),
        load_op,
        store_op: AttachmentStoreOp::Store,
        clear_color: None,
    };
    let begin = |load_op| CommandOp::BeginPass {
        pass,
        target,
        colors: vec![attachment(load_op)],
        depth_stencil: None,
    };
    let mut ops = vec![begin(AttachmentLoadOp::Load), CommandOp::EndPass];
    strip_empty_load_store_passes(&mut ops);
    assert!(ops.is_empty());
    let mut ops = vec![begin(AttachmentLoadOp::Clear), CommandOp::EndPass];
    strip_empty_load_store_passes(&mut ops);
    assert_eq!(2, ops.len());
    let mut ops = vec![
        begin(AttachmentLoadOp::Load),
        CommandOp::Draw { vertices: 3, instances: 1 },
        CommandOp::EndPass,
    ];
    strip_empty_load_store_passes(&mut ops);
    assert_eq!(3, ops.len());
}

#[test]
fn source_gui_target_validation_admits_only_declared_owned_intermediates() {
    let overlay = Handle::new(crate::render::vulkanic::handles::HandleKind::RenderTarget, 1, 1)
        .expect("overlay handle");
    let owned_raster = Handle::new(crate::render::vulkanic::handles::HandleKind::RenderTarget, 2, 1)
        .expect("owned GUI raster handle");
    let undeclared = Handle::new(crate::render::vulkanic::handles::HandleKind::RenderTarget, 3, 1)
        .expect("undeclared target handle");
    let pass =
        Handle::new(crate::render::vulkanic::handles::HandleKind::RenderPass, 1, 1).expect("pass handle");
    let owned_ops = vec![
        CommandOp::BeginPass {
            pass,
            target: owned_raster,
            colors: Vec::new(),
            depth_stencil: None,
        },
        CommandOp::Draw {
            vertices: 3,
            instances: 1,
        },
        CommandOp::EndPass,
        CommandOp::BeginPass {
            pass,
            target: overlay,
            colors: Vec::new(),
            depth_stencil: None,
        },
        CommandOp::Draw {
            vertices: 3,
            instances: 1,
        },
        CommandOp::EndPass,
    ];
    WorldPrimitiveFrontend::validate_source_gui_ops(&owned_ops, overlay, &[owned_raster])
        .expect("declared Rust-owned GUI raster target remains valid");

    let error = WorldPrimitiveFrontend::validate_source_gui_ops(
        &[
            CommandOp::BeginPass {
                pass,
                target: undeclared,
                colors: Vec::new(),
                depth_stencil: None,
            },
            CommandOp::Draw {
                vertices: 3,
                instances: 1,
            },
        ],
        overlay,
        &[owned_raster],
    )
    .expect_err("undeclared target must not enter a selected source frame");
    assert!(error.to_string().contains("undeclared target"));

    let missing_draw = WorldPrimitiveFrontend::validate_source_gui_ops(
        &[CommandOp::BeginPass {
            pass,
            target: overlay,
            colors: Vec::new(),
            depth_stencil: None,
        }],
        overlay,
        &[],
    )
    .expect_err("a GUI render pass without a Rust draw must fail closed");
    assert!(missing_draw
        .to_string()
        .contains("GUI command list opened a render pass without a Rust draw"));
}

